/* ARLAB Performance Hub PRO X5 - planificación Excel editable + colores */
const STORAGE_KEY = 'arlab-performance-hub-pro-x5';
const SAVE_DELAY = 450;
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => Array.from(root.querySelectorAll(s));
const uid = () => (crypto?.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(16).slice(2)}`);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const num = v => { const n = Number(String(v ?? '').replace(',','.')); return Number.isFinite(n) ? n : 0; };
const fmt = (n, d=1) => Number(n||0).toLocaleString('es-ES',{maximumFractionDigits:d});
const todayISO = () => new Date().toISOString().slice(0,10);
const dateFrom = iso => { const d = new Date(`${iso || todayISO()}T00:00:00`); return Number.isNaN(d.getTime()) ? new Date() : d; };
const iso = d => d.toISOString().slice(0,10);
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate()+n); return x; };
const fmtDate = isoDate => dateFrom(isoDate).toLocaleDateString('es-ES',{day:'2-digit',month:'short'});
const fmtFull = isoDate => dateFrom(isoDate).toLocaleDateString('es-ES',{weekday:'short', day:'2-digit', month:'short'});
const weekday = isoDate => dateFrom(isoDate).toLocaleDateString('es-ES',{weekday:'long'});
const monthTitle = d => d.toLocaleDateString('es-ES',{month:'long', year:'numeric'}).replace(/^./, c=>c.toUpperCase());
const playerName = p => [p?.firstName,p?.lastName].filter(Boolean).join(' ') || p?.name || '';
const initials = name => String(name||'J').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join('') || 'J';
function toast(msg){ const n=document.createElement('div'); n.className='toast'; n.textContent=msg; $('#toastHost').appendChild(n); setTimeout(()=>n.remove(),3800); }
function debounce(fn, ms){ let t; return (...args)=>{ clearTimeout(t); t=setTimeout(()=>fn(...args),ms); }; }

const eventTypes = ['Co','Op','Pa','Vi','VD','Red','Ot','Va','Cop'];
const sessionTypes = ['Campo','Fuerza','Vídeo','Partido','Readaptación','Valoración','Coadyuvante','Optimización'];
const availabilityList = ['Disponible','Parcial','Readaptación','Fisio','No disponible','Lesión','Descanso','Selección'];
const taskBlocks = ['Activación grupal','Parte inicial','Parte principal','Vuelta a la calma','Compensatorio','Readaptación'];
const tabs = [
  ['dashboard','Inicio'],['planning','Planificación'],['session','Sesión'],['tasks','Tareas'],['svivo','SVIVO campo'],['check','Check-in/out'],['players','Jugadores'],['devices','Dispositivos'],['reports','Informes'],['history','Historial'],['online','Online']
];

