function defaultHrZones(){return [
  {name:'Z1 Recuperación',min:0,max:60,color:'#60a5fa'},
  {name:'Z2 Aeróbica',min:60,max:70,color:'#22c55e'},
  {name:'Z3 Tempo',min:70,max:80,color:'#facc15'},
  {name:'Z4 Alta',min:80,max:90,color:'#fb923c'},
  {name:'Z5 Máxima',min:90,max:100,color:'#ef4444'}
]}
function defaultSpeedZones(){return [
  {name:'Z1 Baja',min:0,max:7,color:'#60a5fa'},
  {name:'Z2 Moderada',min:7,max:14,color:'#22c55e'},
  {name:'Z3 Alta',min:14,max:21,color:'#facc15'},
  {name:'Z4 Muy alta',min:21,max:24,color:'#fb923c'},
  {name:'Z5 Sprint',min:24,max:40,color:'#ef4444'}
]}
function makePlayer(data={}){
  return {id:data.id||uid(),firstName:data.firstName||'',lastName:data.lastName||'',photo:data.photo||'',birthDate:data.birthDate||'',weight:data.weight||'',wingspan:data.wingspan||'',wimuName:data.wimuName||'',club:data.club||'A.E. Prat',team:data.team||'Equipo',position:data.position||'',clubId:data.clubId||'',sport:data.sport||'Fútbol',number:data.number||'',description:data.description||'',hrDevice:data.hrDevice||'',maxHr:data.maxHr||'',maxSpeed:data.maxSpeed||'',vo2Max:data.vo2Max||'',vo2MaxSpeed:data.vo2MaxSpeed||'',maxAcc:data.maxAcc||'',maxDec:data.maxDec||'',maxLactate:data.maxLactate||'',lactateSpeed1:data.lactateSpeed1||'',lactateSpeed2:data.lactateSpeed2||'',hrZones:data.hrZones||defaultHrZones(),speedZones:data.speedZones||defaultSpeedZones(),tests:data.tests||[],force:data.force||[],gps:data.gps||[],wellness:data.wellness||[],physio:data.physio||[]};
}
function makeEvent(data={}){
  return {id:data.id||uid(),type:data.type||'Co',sessionType:data.sessionType||'Campo',number:data.number||1,time:data.time||'19:00',duration:data.duration??90,place:data.place||'Campo',load:String(data.load??3),rpe:data.rpe||'',space:data.space||'',material:data.material||'',orientation:data.orientation||'',video:data.video||'',objective:data.objective||'',task:data.task||'',rules:data.rules||'',assignments:data.assignments||{},individual:data.individual||{},physio:data.physio||{},tasks:data.tasks||[]};
}
function makeDay(date, idx=0){ return {id:uid(),date,day:weekday(date),md:'',period:'',subperiod:'',rival:'',availability:'',am:'',pm:'',load:'0',comment:'',comments:{CT:'',CPF:'',CSM:'',CFR:'',CN:'',CPS:'',CO:''},controls:{CMJ:'',Galgas:'',Encoder:'',Lactato:'',Pliegues:'','RPE wellness':'',Vídeo:'',Fisio:'',Readaptación:''},events:[]}; }
function createSeason(start='2025-07-01', end='2026-06-30'){
  const days=[]; let d=dateFrom(start); const last=dateFrom(end); let i=0;
  while(d<=last && i<380){ days.push(makeDay(iso(d),i)); d=addDays(d,1); i++; }
  return {name:`Temporada ${start.slice(0,4)}/${String(Number(start.slice(2,4))+1).padStart(2,'0')}`,start,end,activeWeekStart:start,activeDay:0,days};
}
function defaultState(){
  const planning=createSeason();
  planning.days[0].period='P'; planning.days[0].subperiod='Semana competición'; planning.days[0].md='-6 MD'; planning.days[0].events.push(makeEvent({number:1,sessionType:'Campo',type:'Co',time:'19:00',objective:'Sesión de campo'}));
  return {tab:'dashboard',players:defaultPlayers(),activePlayerId:null,activeDeviceId:'polar',planning,results:[],tasks:[],sessions:[],wellness:[],checkouts:[],reports:[],online:{mode:'Local',room:'A',endpoint:'',apiKey:'',queue:[],lastSync:''},devices:defaultDevices(),ui:{planningView:'macro',profileTab:'resumen',sessionType:'Campo',taskSlideIndex:0,selectedTool:'playerRed',svivoDemo:false,selectedObjectId:null},force:{capturing:false,samples:[],rolling:2,device:'tindeq',mode:'Isométrico',exercise:'Isométrico aductores',side:'General',sampleHz:80},ant:{vendorId:'0x0fcf',productId:'0x1008',deviceNumber:'0',channel:'0',frequency:'57',networkKey:'',status:'sin conectar'},bridge:{serviceUuid:'',characteristicUuid:'',parser:'utf8-json',device:'wimu'},designer:{slides:[blankSlide()]},clipboard:null};
}
function defaultDevices(){return [
  {id:'polar',name:'Polar Verity Sense',status:'desconectado',last:null},
  {id:'wimu',name:'WIMU GPS',status:'desconectado',last:null},
  {id:'vitruve',name:'Vitruve Encoder',status:'desconectado',last:null},
  {id:'tindeq',name:'Tindeq Progressor',status:'desconectado',last:null},
  {id:'meloq',name:'Meloq',status:'desconectado',last:null},
  {id:'activeforce2',name:'ActiveForce2',status:'desconectado',last:null},
  {id:'chronojump',name:'Chronojump',status:'desconectado',last:null},
  {id:'ant',name:'ANT+ USB',status:'desconectado',last:null}
]}
function blankSlide(){return {id:uid(),name:'Tarea 1',type:'Campo',objects:[{id:uid(),kind:'playerRed',x:36,y:52,label:'A',size:1.2},{id:uid(),kind:'playerBlue',x:60,y:52,label:'B',size:1.2},{id:uid(),kind:'ball',x:50,y:53,label:'',size:1}],meta:{title:'Nueva tarea',block:'Parte principal',duration:10,space:'40x30',players:'8v8',objective:'',rules:'',material:'Balones, conos',coaching:''}}}
let state = loadState();
let saveTimer = null; let demoIntervals = {}; let currentDrag = null;
function loadState(){ try{ const raw=localStorage.getItem(STORAGE_KEY); if(raw){ const s=JSON.parse(raw); return hydrate(s); } }catch(e){} return defaultState(); }
function hydrate(s){
  const d=defaultState();
  s={...d,...s};
  s.players=(s.players?.length?s.players:d.players).map(makePlayer);
  s.devices=(s.devices?.length?s.devices:d.devices);
  s.planning=s.planning?.days?.length?s.planning:d.planning;
  s.planning.days=s.planning.days.map((day,i)=>({...makeDay(day.date||iso(addDays(dateFrom(s.planning.start),i)),i),...day,events:(day.events||[]).map(makeEvent)}));
  s.designer=s.designer||d.designer; if(!s.designer.slides?.length) s.designer.slides=[blankSlide()]; s.designer.slides.forEach(sl=>{sl.objects=(sl.objects||[]).map(o=>({size:o.size||1,color:o.color||'',label:o.label||'',...o}));});
  s.online=s.online||d.online; s.online.queue=s.online.queue||[]; s.ant=s.ant||d.ant; s.bridge=s.bridge||d.bridge; s.force=s.force||d.force; s.ui={...d.ui,...s.ui};
  return s;
}
const saveState = debounce(()=>{ try{ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }catch(e){ pruneHeavy(); localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); } }, SAVE_DELAY);
function pruneHeavy(){ state.results=state.results.slice(-350); state.force.samples=state.force.samples.slice(-1200); state.players.forEach(p=>{p.tests=(p.tests||[]).slice(-80);p.force=(p.force||[]).slice(-80);p.gps=(p.gps||[]).slice(-80);p.wellness=(p.wellness||[]).slice(-80);}); toast('Caché pesada limpiada automáticamente'); }
function hardSave(){ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }
function activePlayer(){return state.players.find(p=>p.id===state.activePlayerId)||state.players[0];}
function getDevice(id){return state.devices.find(d=>d.id===id)||state.devices[0];}
function activeDevice(){return getDevice(state.activeDeviceId);}
function avatarHtml(p, cls='avatar'){ const name=playerName(p); return `<span class="${cls}">${p?.photo?`<img src="${p.photo}" alt="${esc(name)}">`:esc(initials(name))}</span>`; }
function weekStartOf(dateIso){ const d=dateFrom(dateIso); const day=(d.getDay()+6)%7; return iso(addDays(d,-day)); }
function activeWeekDays(){ const ws=state.planning.activeWeekStart || weekStartOf(state.planning.start); return Array.from({length:7},(_,i)=>findDay(iso(addDays(dateFrom(ws),i))) || makeDay(iso(addDays(dateFrom(ws),i)),i)); }
function findDay(dateIso){return state.planning.days.find(d=>d.date===dateIso);}
function getActiveEvent(){ const day=state.planning.days[state.planning.activeDay]||state.planning.days[0]; const ev=day?.events?.find(e=>e.id===state.activeEventId)||day?.events?.[0]; return {day,event:ev}; }
function assignedPlayers(ev){ if(!ev) return state.players; const ids=Object.entries(ev.assignments||{}).filter(([,r])=>r.selected).map(([id])=>id); return ids.length?state.players.filter(p=>ids.includes(p.id)):state.players; }
function assignmentRecord(ev,pid){ ev.assignments=ev.assignments||{}; if(!ev.assignments[pid]) ev.assignments[pid]={selected:false,minutes:ev.duration||0,availability:'Disponible',role:''}; return ev.assignments[pid]; }
function isAssigned(ev,pid){ return Boolean(ev?.assignments?.[pid]?.selected); }
function availabilityOptions(selected='Disponible'){return availabilityList.map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}
function availabilityClass(value=''){
  const key=String(value||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  if(key.includes('disponible')) return 'avail-disponible';
  if(key.includes('parcial')) return 'avail-parcial';
  if(key.includes('readapt')) return 'avail-readaptacion';
  if(key.includes('fisio')) return 'avail-fisio';
  if(key.includes('lesion')) return 'avail-lesion';
  if(key.includes('no disponible')) return 'avail-no';
  if(key.includes('descanso')) return 'avail-descanso';
  if(key.includes('seleccion')) return 'avail-seleccion';
  return 'avail-empty';
}
function availabilitySelectHtml(selected, attrs=''){
  const cls=availabilityClass(selected);
  return `<select class="cell-select availability-select ${cls}" ${attrs}>${availabilityOptions(selected||'Disponible')}</select>`;
}
function loadSelectHtml(selected, attrs=''){
  return `<select class="cell-select load-select load${selected||0}" ${attrs}>${[0,1,2,3,4,5].map(x=>`<option value="${x}" ${String(selected)===String(x)?'selected':''}>${x}</option>`).join('')}</select>`;
}
function dayValueInput(dateIso, field, value, type='input'){
  if(type==='textarea') return `<textarea class="cell-textarea" data-day-value="${dateIso}|${field}">${esc(value||'')}</textarea>`;
  return `<input class="cell-input" data-day-value="${dateIso}|${field}" value="${esc(value||'')}">`;
}
function ensureDayPlanningEvent(dateIso){
  const d=findDay(dateIso);
  if(!d) return null;
  if(!d.events.length){
    d.events.push(makeEvent({number:1,sessionType:'Campo',type:'Co',time:'19:00',duration:90,place:'Campo',objective:'Evento creado desde micro'}));
  }
  return d.events[0];
}
function updateDayValue(dateIso, field, value){
  const d=findDay(dateIso); if(!d) return;
  if(field.startsWith('control:')) d.controls[field.slice(8)]=value;
  else if(field.startsWith('comment:')) d.comments[field.slice(8)]=value;
  else d[field]=value;
  saveState();
}
function getHrZone(p,hr){ const pct=p.maxHr?hr/Number(p.maxHr)*100:0; const z=(p.hrZones||defaultHrZones()).find(z=>pct>=Number(z.min)&&pct<Number(z.max)) || (p.hrZones||defaultHrZones()).at(-1); return {pct,z}; }
function getSpeedZone(p,speed){ const z=(p.speedZones||defaultSpeedZones()).find(z=>speed>=Number(z.min)&&speed<Number(z.max)) || (p.speedZones||defaultSpeedZones()).at(-1); return z; }
function queue(type,payload){ state.online.queue.unshift({id:uid(),type,payload,createdAt:new Date().toISOString(),status:'pendiente'}); saveState(); }

function render(){
  const app=$('#app');
  const p=activePlayer(); const dev=activeDevice();
  app.innerHTML = `<aside class="sidebar"><div class="brand"><div class="logo">A</div><div><h1>ARLAB</h1><small>Performance Hub PRO X3</small></div></div><nav class="nav">${tabs.map(([id,label])=>`<button class="${state.tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</nav><div class="side-card"><p class="side-label">Jugador activo</p><div class="mini-player">${avatarHtml(p)}<div><b>${esc(playerName(p))}</b><br><small>${esc(p.team)} · ${esc(p.position)}</small></div></div></div><div class="side-card"><p class="side-label">Dispositivo activo</p><select class="full" id="activeDeviceSelect">${state.devices.map(d=>`<option value="${d.id}" ${d.id===state.activeDeviceId?'selected':''}>${esc(d.name)}</option>`).join('')}</select><small>${esc(dev.status)}${dev.last?` · ${esc(dev.last.value)} ${esc(dev.last.unit||'')}`:''}</small></div><div class="side-card"><p class="side-label">Acciones rápidas</p><button class="btn full" data-action="simulate">Simular dato</button><button class="btn full" data-action="clearCache" style="margin-top:8px">Limpiar caché pesada</button></div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">PLANIFICACIÓN · CHECK-IN · DISPOSITIVOS · DATOS</p><h2>${titleForTab()}</h2></div><div class="top-actions"><button class="btn" data-action="exportCsv">Exportar datos</button><button class="btn" data-action="backup">Backup JSON</button><label class="btn">Importar JSON<input type="file" id="importJson" accept="application/json" hidden></label></div></header><section class="content">${renderTab()}</section></main>`;
  bindBase();
}
function titleForTab(){return Object.fromEntries(tabs)[state.tab]||'ARLAB';}
function renderTab(){
  if(state.tab==='planning')return renderPlanning();
  if(state.tab==='session')return renderSession();
  if(state.tab==='tasks')return renderTasks();
  if(state.tab==='svivo')return renderSvivo();
  if(state.tab==='check')return renderCheck();
  if(state.tab==='players')return renderPlayers();
  if(state.tab==='devices')return renderDevices();
  if(state.tab==='reports')return renderReports();
  if(state.tab==='history')return renderHistory();
  if(state.tab==='online')return renderOnline();
  return renderDashboard();
}
function bindBase(){
  $$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab; saveState(); render();});
  $('#activeDeviceSelect').onchange=e=>{state.activeDeviceId=e.target.value; saveState(); render();};
  $('#importJson')?.addEventListener('change',importJson);
  $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));
  bindTabEvents();
}
function handleAction(action,b){
  if(action==='simulate')simulateData();
  if(action==='clearCache'){pruneHeavy(); localStorage.removeItem('arlab-performance-hub-pro-x2'); toast('Caché pesada limpiada'); hardSave(); render();}
  if(action==='exportCsv')exportCsv();
  if(action==='backup')backupJson();
}
function renderDashboard(){
  const week=activeWeekDays(); const events=week.flatMap(d=>d.events.map(e=>({d,e}))); const doneWell=state.wellness.filter(w=>w.date===todayISO()).length;
  return `<div class="grid kpi"><div class="kpi-card"><b>${state.players.length}</b><span>Jugadores</span></div><div class="kpi-card"><b>${events.length}</b><span>Eventos semana</span></div><div class="kpi-card"><b>${state.results.length}</b><span>Registros</span></div><div class="kpi-card"><b>${doneWell}</b><span>Wellness hoy</span></div></div><div class="split"><div class="panel"><div class="panel-title"><h3>Agenda semana</h3><small>Desde planificación</small></div>${events.map(({d,e})=>`<div class="event-card"><b>${fmtFull(d.date)} · ${e.time} · ${e.sessionType}</b><br><small>${e.type}${e.number} · ${e.duration}' · Carga ${e.load}</small><p>${esc(e.objective||e.task||'Sin objetivo')}</p><button class="btn small primary" data-enter-session="${state.planning.days.indexOf(d)}|${e.id}">Entrar sesión</button></div>`).join('')||'<p class="muted">Sin eventos esta semana.</p>'}</div><div class="panel"><div class="panel-title"><h3>Modo app / rendimiento</h3><small>Uso recomendado</small></div><p>PC o tablet campo conecta dispositivos, jugador rellena wellness desde link, staff ve datos online. La app guarda local y sincroniza cuando haya endpoint real.</p><div class="toolbar-row"><button class="btn primary" data-tab="planning">Planificar</button><button class="btn" data-tab="session">Sesión</button><button class="btn" data-tab="svivo">SVIVO campo</button><button class="btn" data-tab="online">Online</button></div></div></div>`;
}

function renderPlanning(){
  const view=state.ui.planningView||'macro';
  return `<div class="tabs planning-tabs"><button class="${view==='macro'?'active':''}" data-plan-view="macro">Macro temporada</button><button class="${view==='micro'?'active':''}" data-plan-view="micro">Micro 7 días</button><button class="${view==='dia'?'active':''}" data-plan-view="dia">Día / eventos</button></div><div class="panel plan-header-pro"><div class="panel-title"><div><h3>Planificación tipo Excel · editable en celda</h3><small>Escribe directamente, cambia disponibilidad con color, añade comentarios y abre eventos para asignar jugadores.</small></div><div><button class="btn" data-action-plan="fixDates">Arreglar fechas</button><button class="btn primary" data-action-plan="newSeason">Nueva temporada</button></div></div><div class="form-grid"><label class="field">Inicio temporada<input id="seasonStart" type="date" value="${state.planning.start}"></label><label class="field">Fin temporada<input id="seasonEnd" type="date" value="${state.planning.end}"></label><label class="field">Nombre<input id="seasonName" value="${esc(state.planning.name)}"></label><label class="field">Semana activa<select id="activeWeekSelect">${weekOptions()}</select></label></div><div class="planning-legend"><span class="avail-chip avail-disponible">Disponible</span><span class="avail-chip avail-parcial">Parcial</span><span class="avail-chip avail-readaptacion">Readaptación</span><span class="avail-chip avail-fisio">Fisio</span><span class="avail-chip avail-lesion">Lesión</span><span class="avail-chip avail-no">No disponible</span><span class="load-chip load1">C1</span><span class="load-chip load2">C2</span><span class="load-chip load3">C3</span><span class="load-chip load4">C4</span><span class="load-chip load5">C5</span></div></div>${view==='macro'?renderMacro():view==='micro'?renderMicro():renderDayView()}`;
}
function weekOptions(){ const starts=[]; const start=dateFrom(state.planning.start); const end=dateFrom(state.planning.end); let d=dateFrom(weekStartOf(state.planning.start)); let i=1; while(d<=end&&i<60){ const val=iso(d); const label=`S${i} · ${fmtDate(val)} → ${fmtDate(iso(addDays(d,6)))}`; starts.push(`<option value="${val}" ${val===state.planning.activeWeekStart?'selected':''}>${label}</option>`); d=addDays(d,7); i++; } return starts.join(''); }
function renderMacro(){
  const days=state.planning.days;
  const rows=['Día','MD','Periodo','Subperiodo','Rival','Disponibilidad','AM','PM','Carga','Comentario micro','EVENTOS','Eventos','CMJ','Galgas','Encoder','Lactato','Pliegues','RPE wellness','Vídeo','Fisio','Readaptación','CT','CPF','CSM','CFR','CN','CPS','CO'];
  return `<div class="panel planning-super"><div class="panel-title"><div><h3>Macro temporada completa · plantilla tipo Excel</h3><small>${state.planning.start} → ${state.planning.end}. Vista larga como Excel: contexto, dinámica, controles, staff y eventos. Doble clic/clic en evento para abrir.</small></div><div class="toolbar-row"><button class="btn" data-action-plan="exportPlanning">Exportar planificación</button><button class="btn" data-action-plan="fixDates">Recalcular temporada</button></div></div>${renderSeasonNavigator()}<div class="excel-wrap macro-excel"><table class="excel-table planning-matrix"><thead><tr><th class="rowhead">PLANTILLA PLANIFICACIÓN</th>${days.map((d,i)=>`<th class="${isWeekend(d.date)?'weekend':''} ${isMonday(d.date)?'week-start':''}"><span>${fmtDate(d.date)}</span><br><small>${dateFrom(d.date).toLocaleDateString('es-ES',{weekday:'short'})}</small><br><button class="btn small" data-open-day="${i}">Día</button></th>`).join('')}</tr></thead><tbody>${rows.map(r=>macroRow(r,days)).join('')}</tbody></table></div></div>`;
}
function isMonday(dateIso){return dateFrom(dateIso).getDay()===1;}
function renderSeasonNavigator(){
  const byMonth=[]; let current=''; let weeks=[];
  state.planning.days.forEach((d,i)=>{ const m=monthTitle(dateFrom(d.date)); if(m!==current){ if(current)byMonth.push({month:current,weeks}); current=m; weeks=[]; } if(isMonday(d.date)||i===0){ const weekDays=state.planning.days.slice(i,i+7); const evCount=weekDays.reduce((a,x)=>a+x.events.length,0); const load=weekDays.reduce((a,x)=>a+num(x.load),0); weeks.push({i,date:d.date,evCount,load}); }});
  if(current)byMonth.push({month:current,weeks});
  return `<div class="season-map">${byMonth.map(m=>`<div class="season-month"><b>${esc(m.month)}</b><div>${m.weeks.map(w=>`<button class="week-dot ${weekStartOf(w.date)===state.planning.activeWeekStart?'active':''}" data-jump-week="${weekStartOf(w.date)}"><span>S${weekNumber(w.date)}</span><small>${w.evCount} ev · C${w.load}</small></button>`).join('')}</div></div>`).join('')}</div>`;
}
function weekNumber(dateIso){ const start=dateFrom(weekStartOf(state.planning.start)); return Math.floor((dateFrom(weekStartOf(dateIso))-start)/(7*24*3600*1000))+1; }
function macroRow(label,days){
  if(label==='EVENTOS')return `<tr class="section-row"><td class="rowhead">EVENTOS ESPECÍFICOS</td>${days.map(()=>'<td></td>').join('')}</tr>`;
  const section=['CMJ','CT'].includes(label); if(section){ const s=label==='CMJ'?'CONTROL / VALORACIÓN':'COMENTARIOS STAFF'; return `<tr class="section-row"><td class="rowhead">${s}</td>${days.map(()=>'<td></td>').join('')}</tr>`; }
  const isEventRow=label.startsWith('Evento ');
  return `<tr><td class="rowhead">${label}</td>${days.map((d)=>macroCell(label,d)).join('')}</tr>`;
}
function macroCell(label,d){
  let cls=isWeekend(d.date)?'weekend':''; let html='';
  if(label==='Día') return `<td class="${cls} day-name-cell"><b>${weekday(d.date)}</b></td>`;
  if(label==='Eventos') return `<td class="event-cell">${d.events.map(e=>`<span class="event-pill open ev-${String(e.type).toLowerCase()}" data-open-event="${state.planning.days.indexOf(d)}|${e.id}"><b>${e.type}${e.number}</b><br><small>${e.time} · ${e.sessionType}</small></span>`).join('')}<button class="btn small" data-new-event="${state.planning.days.indexOf(d)}">+</button></td>`;
  if(label==='Disponibilidad') html=availabilitySelectHtml(d.availability||'',`data-day-value="${d.date}|availability"`);
  else if(label==='Carga') html=loadSelectHtml(d.load||0,`data-day-value="${d.date}|load"`);
  else if(label==='Comentario micro') html=dayValueInput(d.date,'comment',d.comment,'textarea');
  else if(['MD','Periodo','Subperiodo','Rival','AM','PM'].includes(label)){
    const field={MD:'md',Periodo:'period',Subperiodo:'subperiod',Rival:'rival',AM:'am',PM:'pm'}[label];
    html=dayValueInput(d.date,field,d[field]);
  } else if(d.controls&&label in d.controls){ html=dayValueInput(d.date,`control:${label}`,d.controls[label]); }
  else if(d.comments&&label in d.comments){ html=dayValueInput(d.date,`comment:${label}`,d.comments[label],'textarea'); }
  else html='';
  return `<td class="${cls} editable-cell">${html}</td>`;
}
function renderMicro(){
  const days=activeWeekDays(); const playerRows=state.players;
  const mainRows=['Día','MD','Periodo','Subperiodo','Rival','Disponibilidad','AM','PM','Carga','Comentario micro','Eventos'];
  return `<div class="panel micro-planner"><div class="panel-title"><div><h3>Micro 7 días · Excel editable con jugadores</h3><small>${fmtDate(days[0].date)} → ${fmtDate(days[6].date)}. Edita en las celdas: contexto, eventos, asignación, minutos, disponibilidad por color, comentarios individuales y fisio.</small></div><div><button class="btn" data-week-shift="-7">← Semana anterior</button><button class="btn" data-week-shift="7">Semana siguiente →</button><button class="btn" data-copy-day>Copiar día activo</button><button class="btn" data-paste-day>Pegar día activo</button></div></div><div class="micro-day-strip">${days.map(d=>`<button class="micro-day-card ${state.planning.days.indexOf(d)===state.planning.activeDay?'active':''}" data-open-day="${state.planning.days.indexOf(d)}"><b>${fmtDate(d.date)}</b><span>${weekday(d.date)}</span><em>${d.events.length} eventos · Carga ${d.load||0}</em></button>`).join('')}</div><div class="excel-wrap"><table class="excel-table micro-matrix"><thead><tr><th class="rowhead">MICRO SEMANA</th>${days.map((d)=>`<th class="${state.planning.days.indexOf(d)===state.planning.activeDay?'active':''}">${fmtDate(d.date)}<br><small>${weekday(d.date)}</small><br><button class="btn small" data-open-day="${state.planning.days.indexOf(d)}">Abrir día</button></th>`).join('')}</tr></thead><tbody>${mainRows.map(r=>microRow(r,days)).join('')}<tr class="section-row"><td class="rowhead">ASIGNACIÓN / MINUTOS</td>${days.map(()=>'<td></td>').join('')}</tr>${playerRows.map(p=>microPlayerRow(p,'Asignación',days)).join('')}<tr class="section-row"><td class="rowhead">DISPONIBILIDAD</td>${days.map(()=>'<td></td>').join('')}</tr>${playerRows.map(p=>microPlayerRow(p,'Disponibilidad',days)).join('')}<tr class="section-row"><td class="rowhead">COMENTARIOS INDIVIDUALES</td>${days.map(()=>'<td></td>').join('')}</tr>${playerRows.map(p=>microPlayerRow(p,'Comentarios',days)).join('')}<tr class="section-row"><td class="rowhead">FISIO / READAPTACIÓN</td>${days.map(()=>'<td></td>').join('')}</tr>${playerRows.map(p=>microPlayerRow(p,'Fisio',days)).join('')}</tbody></table></div><div class="micro-tip">Consejo: pulsa un evento para abrir el editor completo. Ahí cambias tipo de sesión, objetivos, tareas, asignaciones, minutos, disponibilidad y comentarios individuales.</div></div>`;
}
function microRow(label,days){return `<tr><td class="rowhead">${label}</td>${days.map(d=>{ if(label==='Eventos')return `<td class="event-cell">${d.events.map(e=>`<span class="event-pill open ev-${String(e.type).toLowerCase()}" data-open-event="${state.planning.days.indexOf(d)}|${e.id}"><b>${e.type}${e.number}</b> ${e.time}<br><small>${e.sessionType} · ${e.duration}' · ${assignedPlayers(e).length} jug.</small></span>`).join('')}<button class="btn small" data-new-event="${state.planning.days.indexOf(d)}">+ evento</button></td>`; return macroCell(label,d); }).join('')}</tr>`;}
function microPlayerRow(p,type,days){
  return `<tr><td class="rowhead player-rowhead">${avatarHtml(p,'avatar-xs')} <span>${esc(playerName(p))}<small>${esc(p.position||'')}</small></span></td>${days.map(d=>microPlayerCell(p,type,d)).join('')}</tr>`;
}
function microPlayerCell(p,type,d){
  const ev=d.events[0];
  const r=ev?.assignments?.[p.id] || {selected:false,minutes:0,availability:'',role:''};
  const ind=ev?.individual?.[p.id]||'';
  const ph=ev?.physio?.[p.id]||{};
  const evLabel=ev?`<span class="mini-ev-label">${ev.type}${ev.number}</span>`:`<span class="mini-ev-label muted">sin ev.</span>`;
  if(type==='Asignación') return `<td class="player-day-cell assignment-inline ${r.selected?'selected':''}">${evLabel}<label class="inline-check"><input type="checkbox" data-pd-assign="${d.date}|${p.id}" ${r.selected?'checked':''}> Sel</label><input class="tiny-number" type="number" min="0" max="130" data-pd-min="${d.date}|${p.id}" value="${esc(r.minutes||0)}"><input class="tiny-role" placeholder="rol/grupo" data-pd-role="${d.date}|${p.id}" value="${esc(r.role||'')}"></td>`;
  if(type==='Disponibilidad') return `<td class="player-day-cell ${availabilityClass(r.availability)}">${evLabel}${availabilitySelectHtml(r.availability||'Disponible',`data-pd-avail="${d.date}|${p.id}"`)}</td>`;
  if(type==='Comentarios') return `<td class="player-day-cell comment-inline">${evLabel}<textarea data-pd-comment="${d.date}|${p.id}" placeholder="Comentario individual">${esc(ind)}</textarea></td>`;
  if(type==='Fisio') return `<td class="player-day-cell physio-inline ${ph.done?'physio-done':''}">${evLabel}<label class="inline-check"><input type="checkbox" data-pd-fisio="${d.date}|${p.id}" ${ph.done?'checked':''}> Fisio</label><textarea data-pd-fisio-note="${d.date}|${p.id}" placeholder="Tratamiento / RDP">${esc(ph.note||'')}</textarea></td>`;
  return '<td></td>';
}
function renderDayView(){
  const day=state.planning.days[state.planning.activeDay]||state.planning.days[0];
  return `<div class="day-events-layout"><div class="panel"><div class="panel-title"><div><h3>Vista día · ${fmtFull(day.date)}</h3><small>Eventos como Excel: tipo, sesión, hora, minutos, lugar, carga, RPE, objetivo y tareas.</small></div><button class="btn primary" data-new-event="${state.planning.activeDay}">+ Nuevo evento</button></div>${day.events.map(ev=>renderEventCard(day,ev)).join('')||'<p class="muted">Sin eventos. Crea uno para entrar a sesión.</p>'}</div><div class="panel event-editor"><h3>Resumen del día</h3><div class="form-grid two"><label class="field">Día<input value="${fmtFull(day.date)}" readonly></label><label class="field">Carga<input data-day-field="load" value="${esc(day.load)}"></label><label class="field">MD<input data-day-field="md" value="${esc(day.md)}"></label><label class="field">Rival<input data-day-field="rival" value="${esc(day.rival)}"></label><label class="field" style="grid-column:1/-1">Comentario<textarea data-day-field="comment">${esc(day.comment)}</textarea></label></div><div class="toolbar-row"><button class="btn" data-copy-day>Copiar día</button><button class="btn" data-paste-day>Pegar día</button></div></div></div>`;
}
function renderEventCard(day,ev){
  const assigned=assignedPlayers(ev);
  return `<div class="event-card ${state.activeEventId===ev.id?'active':''}"><div class="panel-title"><div><h3>${ev.type}${ev.number} · ${ev.sessionType} · ${ev.time}</h3><small>${ev.duration}' · ${ev.place} · carga ${ev.load} · ${assigned.length} jugadores</small></div><div><button class="btn small" data-open-event="${state.planning.days.indexOf(day)}|${ev.id}">Abrir evento</button><button class="btn small primary" data-enter-session="${state.planning.days.indexOf(day)}|${ev.id}">Entrar sesión</button></div></div><p><b>Objetivo:</b> ${esc(ev.objective||'-')}</p><p><b>Tarea:</b> ${esc(ev.task||'-')}</p>${renderAssignmentsCompact(ev)}</div>`;
}
function renderAssignmentsCompact(ev){ const selected=state.players.filter(p=>isAssigned(ev,p.id)); return `<div class="assignment-table-wrap"><table class="assignment-table"><thead><tr><th>Jugador</th><th>Min</th><th>Disponibilidad</th><th>Comentario</th><th>Fisio</th></tr></thead><tbody>${(selected.length?selected:state.players.slice(0,8)).map(p=>{const r=assignmentRecord(ev,p.id);return `<tr class="${r.selected?'selected':''}"><td class="player-cell">${avatarHtml(p,'avatar-sm')}<b>${esc(playerName(p))}</b></td><td>${r.minutes||0}</td><td>${esc(r.availability||'')}</td><td>${esc(ev.individual?.[p.id]||'')}</td><td>${esc(ev.physio?.[p.id]?.note||'')}</td></tr>`}).join('')}</tbody></table></div>`; }
function isWeekend(date){ const d=dateFrom(date).getDay(); return d===0||d===6; }

function openEventModal(dayIndex,eventId){
  const day=state.planning.days[dayIndex]; if(!day) return; const ev=eventId?day.events.find(e=>e.id===eventId):makeEvent({number:day.events.length+1,duration:90}); const isNew=!eventId;
  const rows=state.players.map(p=>{const r=assignmentRecord(ev,p.id); const ph=ev.physio?.[p.id]||{}; return `<tr><td class="player-cell">${avatarHtml(p,'avatar-sm')}<div><b>${esc(playerName(p))}</b><br><small>${esc(p.team)} · ${esc(p.position)}</small></div></td><td><input type="checkbox" data-modal-assign="${p.id}" ${r.selected?'checked':''}></td><td><input type="number" min="0" max="130" data-modal-minutes="${p.id}" value="${esc(r.minutes??ev.duration??0)}"></td><td><select data-modal-availability="${p.id}">${availabilityOptions(r.availability||'Disponible')}</select></td><td><input data-modal-role="${p.id}" value="${esc(r.role||'')}"></td><td><textarea data-modal-individual="${p.id}" placeholder="Comentario individual">${esc(ev.individual?.[p.id]||'')}</textarea></td><td><label class="tiny-check"><input type="checkbox" data-modal-physio="${p.id}" ${ph.done?'checked':''}> Fisio</label><textarea data-modal-physio-note="${p.id}" placeholder="Qué se ha hecho">${esc(ph.note||'')}</textarea></td></tr>`}).join('');
  $('#modalHost').innerHTML=`<div class="modal-backdrop"><div class="modal modal-wide"><div class="panel-title"><h3>${isNew?'Nuevo evento':'Editar evento'} · ${fmtFull(day.date)}</h3><button class="btn" data-close-modal>Cerrar</button></div><div class="form-grid"><label class="field">Tipo<select id="mType">${eventTypes.map(t=>`<option ${ev.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Sesión<select id="mSessionType">${sessionTypes.map(t=>`<option ${ev.sessionType===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Nº<input id="mNumber" type="number" value="${ev.number}"></label><label class="field">Hora<input id="mTime" type="time" value="${ev.time}"></label><label class="field">Minutos<input id="mDuration" type="number" value="${ev.duration}"></label><label class="field">Lugar<input id="mPlace" value="${esc(ev.place)}"></label><label class="field">Carga<select id="mLoad">${[0,1,2,3,4,5].map(x=>`<option value="${x}" ${String(ev.load)===String(x)?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">RPE<input id="mRpe" value="${esc(ev.rpe)}"></label><label class="field">Espacio<input id="mSpace" value="${esc(ev.space)}"></label><label class="field">Material<input id="mMaterial" value="${esc(ev.material)}"></label><label class="field">Orientación<input id="mOrientation" value="${esc(ev.orientation)}"></label><label class="field">Vídeo<input id="mVideo" value="${esc(ev.video)}"></label><label class="field" style="grid-column:1/-1">Objetivo<textarea id="mObjective">${esc(ev.objective)}</textarea></label><label class="field" style="grid-column:1/-1">Tarea<textarea id="mTask">${esc(ev.task)}</textarea></label><label class="field" style="grid-column:1/-1">Normas<textarea id="mRules">${esc(ev.rules)}</textarea></label></div><div class="modal-section-title">Asignación jugadores · minutos · disponibilidad · comentarios individuales · fisio</div><div class="toolbar-row"><button class="btn" data-modal-all>Equipo completo</button><button class="btn danger" data-modal-clear>Limpiar asignación</button></div><div class="assignment-table-wrap"><table class="assignment-table"><thead><tr><th>Jugador</th><th>Sel.</th><th>Min.</th><th>Disponibilidad</th><th>Grupo/Rol</th><th>Comentario</th><th>Fisio/RDP</th></tr></thead><tbody>${rows}</tbody></table></div><div style="margin-top:14px"><button class="btn primary" data-save-event="${dayIndex}|${ev.id}|${isNew?'new':'edit'}">Guardar evento</button> <button class="btn success" data-save-event-session="${dayIndex}|${ev.id}|${isNew?'new':'edit'}">Guardar y entrar sesión</button> ${!isNew?`<button class="btn danger" data-delete-event="${dayIndex}|${ev.id}">Borrar</button>`:''}</div></div></div>`;
  bindModal();
}
function bindModal(){
  $('[data-close-modal]')?.addEventListener('click',()=>$('#modalHost').innerHTML='');
  $('[data-modal-all]')?.addEventListener('click',()=>$$('[data-modal-assign]').forEach(x=>x.checked=true));
  $('[data-modal-clear]')?.addEventListener('click',()=>$$('[data-modal-assign]').forEach(x=>x.checked=false));
  $('[data-save-event]')?.addEventListener('click',e=>{const [di,id,mode]=e.target.dataset.saveEvent.split('|'); saveEventFromModal(Number(di),id,mode==='new',false)});
  $('[data-save-event-session]')?.addEventListener('click',e=>{const [di,id,mode]=e.target.dataset.saveEventSession.split('|'); saveEventFromModal(Number(di),id,mode==='new',true)});
  $('[data-delete-event]')?.addEventListener('click',e=>{const [di,id]=e.target.dataset.deleteEvent.split('|'); const day=state.planning.days[Number(di)]; day.events=day.events.filter(ev=>ev.id!==id); $('#modalHost').innerHTML=''; saveState(); render();});
}
function saveEventFromModal(dayIndex,eventId,isNew,enter){
  const day=state.planning.days[dayIndex]; let ev=isNew?makeEvent():day.events.find(e=>e.id===eventId); if(!ev)return;
  Object.assign(ev,{type:$('#mType').value,sessionType:$('#mSessionType').value,number:num($('#mNumber').value)||1,time:$('#mTime').value,duration:num($('#mDuration').value),place:$('#mPlace').value,load:$('#mLoad').value,rpe:$('#mRpe').value,space:$('#mSpace').value,material:$('#mMaterial').value,orientation:$('#mOrientation').value,video:$('#mVideo').value,objective:$('#mObjective').value,task:$('#mTask').value,rules:$('#mRules').value});
  ev.assignments={}; ev.individual={}; ev.physio={};
  state.players.forEach(p=>{ const sel=$(`[data-modal-assign="${p.id}"]`).checked; const minutes=num($(`[data-modal-minutes="${p.id}"]`).value); const availability=$(`[data-modal-availability="${p.id}"]`).value; const role=$(`[data-modal-role="${p.id}"]`).value; const ind=$(`[data-modal-individual="${p.id}"]`).value; const phDone=$(`[data-modal-physio="${p.id}"]`).checked; const phNote=$(`[data-modal-physio-note="${p.id}"]`).value; ev.assignments[p.id]={selected:sel,minutes,availability,role}; if(ind)ev.individual[p.id]=ind; if(phDone||phNote)ev.physio[p.id]={done:phDone,note:phNote}; });
  if(isNew)day.events.push(ev); state.planning.activeDay=dayIndex; state.activeEventId=ev.id; $('#modalHost').innerHTML=''; if(enter){state.tab='session'; state.ui.sessionType=ev.sessionType;} saveState(); render(); toast('Evento guardado');
}
function setMacroValue(date,label,value){ const d=findDay(date); if(!d)return; if(label==='MD')d.md=value; else if(label==='Periodo')d.period=value; else if(label==='Subperiodo')d.subperiod=value; else if(label==='Rival')d.rival=value; else if(label==='Disponibilidad')d.availability=value; else if(label==='AM')d.am=value; else if(label==='PM')d.pm=value; else if(label==='Carga')d.load=value; else if(label==='Comentario micro')d.comment=value; else if(d.controls&&label in d.controls)d.controls[label]=value; else if(d.comments&&label in d.comments)d.comments[label]=value; saveState(); }
function fixDates(){ const s=$('#seasonStart')?.value||state.planning.start; const e=$('#seasonEnd')?.value||state.planning.end; state.planning=createSeason(s,e); state.planning.name=$('#seasonName')?.value||state.planning.name; saveState(); render(); toast('Fechas regeneradas'); }

function renderSession(){
  const cur=getActiveEvent(); const ev=cur.event; const day=cur.day; const type=state.ui.sessionType || ev?.sessionType || 'Campo'; const players=assignedPlayers(ev);
  return `<div class="tabs session-modes">${sessionTypes.map(t=>`<button class="${type===t?'active':''}" data-session-type="${t}">${t}</button>`).join('')}</div><div class="session-hero"><div class="session-header-sheet"><div class="sheet-title">${esc(type)} · SESIÓN</div><div class="sheet-meta"><div>📅 ${day?fmtFull(day.date):todayISO()}</div><div>👥 ${players.length} jugadores</div><div>⏱ ${ev?.time||'--:--'} · ${ev?.duration||0}'</div><div>📍 ${ev?.place||'Campo / Gimnasio'}</div></div><div class="sheet-objective"><b>OBJETIVO DE LA SESIÓN:</b> ${esc(ev?.objective||'Selecciona un evento de planificación o crea una sesión libre.')}</div></div><div class="panel"><div class="panel-title"><h3>Evento activo</h3><small>Entrada desde planificación</small></div><label class="field">Evento<select id="sessionEventSelect"><option value="">Sesión libre</option>${state.planning.days.flatMap((d,di)=>d.events.map(e=>`<option value="${di}|${e.id}" ${ev?.id===e.id?'selected':''}>${fmtDate(d.date)} · ${e.time} · ${e.type}${e.number} · ${e.sessionType}</option>`)).join('')}</select></label><div class="toolbar-row"><button class="btn primary" data-tab="tasks">Diseñar tarea</button>${ev?`<button class="btn" data-open-event="${state.planning.activeDay}|${ev.id}">Editar evento</button>`:''}<button class="btn success" data-save-session>Guardar sesión</button></div></div></div>${renderSessionPlayersTable(ev,players)}${['Fuerza','Coadyuvante','Valoración'].includes(type)?renderForceSession(ev,players):['Campo','Partido','Optimización'].includes(type)?renderFieldSession(ev,players):renderGenericSession(type,ev,players)}`;
}
function renderSessionPlayersTable(ev,players){ if(!ev)return '<div class="panel"><p>Selecciona un evento para ver jugadores asignados.</p></div>'; return `<div class="panel"><div class="panel-title"><h3>Jugadores de la sesión</h3><small>Minutos, disponibilidad, comentarios y fisio</small></div><div class="assignment-table-wrap"><table class="assignment-table"><thead><tr><th>Jugador</th><th>Sel.</th><th>Min.</th><th>Disponibilidad</th><th>Grupo/Rol</th><th>Comentario individual</th><th>Fisio/RDP</th></tr></thead><tbody>${state.players.map(p=>{const r=assignmentRecord(ev,p.id); const ph=ev.physio?.[p.id]||{}; return `<tr class="${r.selected?'selected':''}"><td class="player-cell">${avatarHtml(p,'avatar-sm')}<b>${esc(playerName(p))}</b></td><td><input type="checkbox" data-session-assign="${p.id}" ${r.selected?'checked':''}></td><td><input class="mini-input" type="number" data-session-minutes="${p.id}" value="${r.minutes||0}"></td><td><select data-session-availability="${p.id}">${availabilityOptions(r.availability||'Disponible')}</select></td><td><input data-session-role="${p.id}" value="${esc(r.role||'')}"></td><td><textarea data-session-individual="${p.id}">${esc(ev.individual?.[p.id]||'')}</textarea></td><td><label class="tiny-check"><input type="checkbox" data-session-physio="${p.id}" ${ph.done?'checked':''}> Fisio</label><textarea data-session-physio-note="${p.id}">${esc(ph.note||'')}</textarea></td></tr>`}).join('')}</tbody></table></div></div>`; }
function renderFieldSession(ev,players){ return `<div class="panel"><div class="panel-title"><h3>Campo · tareas de la sesión</h3><small>Tipo ficha + editor PowerPoint</small></div><div class="toolbar-row"><button class="btn primary" data-tab="tasks">Abrir editor de tareas</button><button class="btn" data-action-session="addSlideToEvent">Añadir slide actual al evento</button><button class="btn" data-tab="svivo">Ir a SVIVO campo</button></div>${renderTaskCards(ev)}</div><div class="split"><div>${renderPitchDesigner(true)}</div><div>${renderPolarTeam(players)}${renderGpsBox()}</div></div>`; }
function renderTaskCards(ev){ const tasks=(ev?.tasks||[]); return `<div class="task-blocks">${taskBlocks.map(block=>`<div><div class="block-title"><span>${esc(block)}</span></div><div class="exercise-grid">${tasks.filter(t=>t.block===block).map(t=>`<div class="exercise-card"><div class="photo">${esc(t.title||'Tarea')}</div><h4>${esc(t.title)}</h4><table class="mini-matrix"><tr><th>Dur.</th><th>Espacio</th><th>Jug.</th></tr><tr><td>${t.duration||''}'</td><td>${esc(t.space||'')}</td><td>${esc(t.players||'')}</td></tr></table><p style="padding:10px">${esc(t.objective||'')}</p></div>`).join('')||'<p class="muted">Sin tareas en este bloque.</p>'}</div></div>`).join('')}</div>`; }
function renderPolarTeam(players){return `<div class="panel"><div class="panel-title"><h3>Polar Team live</h3><small>ppm · %HRmax · zona</small></div>${players.map(p=>{const hr=getDevice('polar').last?.players?.[p.id]||Math.round(95+Math.random()*70); const {pct,z}=getHrZone(p,hr); return `<div class="live-player"><span style="background:${z.color}" class="avatar-sm">${initials(playerName(p))}</span><div><b>${esc(playerName(p))}</b><br><span class="zone-badge" style="background:${z.color}">${esc(z.name)} · ${fmt(pct,0)}%</span></div><b>${hr} ppm</b></div>`}).join('')}</div>`;}
function renderGpsBox(){return `<div class="panel"><div class="panel-title"><h3>WIMU / GPS sesión</h3><small>BLE · ANT+ · JSON</small></div><div class="grid" style="grid-template-columns:repeat(2,1fr)"><button class="btn primary" data-connect="wimu">Conectar WIMU BLE</button><button class="btn" data-connect="ant">Conectar ANT+ USB</button><button class="btn" data-action-svivo="demo">Demo SVIVO</button><button class="btn" data-action-device="importWimu">Importar JSON WIMU</button></div></div>`}
function renderForceSession(ev,players){return `<div class="panel"><div class="panel-title"><h3>Sesión de fuerza</h3><small>Ficha visual + galgas + encoder</small></div>${renderForceSheet(ev)}</div>${renderForceLab()}${renderEncoderLab()}`;}
function renderForceSheet(ev){ const tasks=ev?.tasks?.filter(t=>t.type==='Fuerza')||[]; return `<div class="session-header-sheet"><div class="sheet-title">EQUIPO · FUERZA</div><div class="sheet-meta"><div>${ev?.time||'--:--'}</div><div>${ev?.duration||0}'</div><div>${ev?.place||'Gimnasio'}</div><div>${ev?.load||''} carga</div></div><div class="sheet-objective"><b>OBJETIVO:</b> ${esc(ev?.objective||'Trabajo estructural y coadyuvante')}</div></div>${taskBlocks.slice(0,4).map(block=>`<div class="block-title"><span>${block}</span></div><div class="exercise-grid">${(tasks.filter(t=>t.block===block).length?tasks.filter(t=>t.block===block):[{title:'Añadir ejercicio',sets:'',reps:'',material:'',objective:''}]).map(t=>`<div class="exercise-card"><div class="photo">${esc(t.title)}</div><h4>${esc(t.title)}</h4><table class="mini-matrix"><tr><th>Material</th><th>Series</th><th>Rep</th></tr><tr><td>${esc(t.material||'')}</td><td>${esc(t.sets||'')}</td><td>${esc(t.reps||'')}</td></tr></table><p style="padding:10px"><b>Comentario:</b> ${esc(t.objective||'')}</p></div>`).join('')}</div>`).join('')}`;}
function renderGenericSession(type,ev,players){return `<div class="panel"><div class="panel-title"><h3>${esc(type)}</h3><small>Sesión específica</small></div><p>Usa la tabla de jugadores, comentarios individuales y entra desde planificación.</p></div>`}

function renderForceLab(){ const f=state.force; const summary=forceSummary(); return `<div class="panel"><div class="panel-title"><h3>Laboratorio galgas · Tindeq / Meloq / ActiveForce2 / Chronojump</h3><small>curva fuerza-tiempo, pico, rolling avg 2s, impulso y RFD</small></div><div class="form-grid"><label class="field">Dispositivo<select id="forceDevice">${['tindeq','meloq','activeforce2','chronojump'].map(x=>`<option value="${x}" ${f.device===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Modo<select id="forceMode">${['Isométrico','Peak force / RFD','Repeticiones','Live stream'].map(x=>`<option ${f.mode===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Ejercicio<input id="forceExercise" value="${esc(f.exercise)}"></label><label class="field">Lado<select id="forceSide">${['General','Derecha','Izquierda','Bilateral'].map(x=>`<option ${f.side===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Rolling segundos<input id="forceRolling" type="number" value="${f.rolling}"></label><label class="field">Frecuencia muestreo<input id="forceHz" type="number" value="${f.sampleHz}"></label></div><div class="toolbar-row"><button class="btn primary" data-force="start">Empezar</button><button class="btn" data-force="stop">Parar</button><button class="btn" data-force="demo">Demo curva</button><button class="btn success" data-force="save">Guardar test completo</button><button class="btn danger" data-force="reset">Reset</button></div><div class="force-stats"><div class="force-stat"><b>${f.samples.length}</b><span>Muestras</span></div><div class="force-stat"><b>${fmt(summary.peak)} N</b><span>Pico</span></div><div class="force-stat"><b>${fmt(summary.roll)} N</b><span>Rolling ${f.rolling}s</span></div><div class="force-stat"><b>${fmt(summary.rfd)} N/s</b><span>RFD 0-200ms</span></div></div><canvas id="forceCanvas" class="force-canvas" width="1100" height="360"></canvas></div>`;}
function renderEncoderLab(){return `<div class="panel"><div class="panel-title"><h3>Encoder / Vitruve VBT</h3><small>BLE bridge + manual + CSV</small></div><div class="form-grid"><label class="field">Ejercicio<input id="vbtExercise" value="Sentadilla"></label><label class="field">Carga kg<input id="vbtLoad" type="number" value="60"></label><label class="field">Vel. media<input id="vbtMean" type="number" step="0.01" value="0.75"></label><label class="field">Vel. pico<input id="vbtPeak" type="number" step="0.01" value="0.98"></label></div><div class="toolbar-row"><button class="btn primary" data-connect="vitruve">Conectar Vitruve BLE</button><button class="btn" data-vbt="addRep">Añadir rep</button><button class="btn success" data-vbt="saveSet">Guardar serie VBT</button></div><div id="vbtReps" class="assignment-table-wrap"><table class="result-table"><tr><th>Rep</th><th>Vel media</th><th>Vel pico</th><th>Potencia est.</th><th>Pérdida</th></tr>${(state.vbtReps||[]).map((r,i)=>`<tr><td>${i+1}</td><td>${r.mean}</td><td>${r.peak}</td><td>${r.power}</td><td>${r.loss}%</td></tr>`).join('')}</table></div></div>`}

function renderTasks(){ return `<div class="tabs"><button class="active">Diseñador tipo PowerPoint</button><button>Banco tareas</button><button>Constructor sesión</button></div>${renderTaskPowerpoint()}${renderSessionBuilder()}${renderTaskBank()}`; }
function renderSessionBuilder(){ const ev=getActiveEvent().event; const tasks=(ev?.tasks||[]); return `<div class="panel session-builder"><div class="panel-title"><div><h3>Constructor de sesión</h3><small>Ordena las tareas por bloques y crea una sesión completa desde el diseñador.</small></div><button class="btn primary" data-slide="sendSession">Añadir slide actual al evento</button></div><div class="session-block-grid">${taskBlocks.map(block=>{const blockTasks=tasks.filter(t=>t.block===block);return `<div class="session-block-card"><h4>${block}</h4>${blockTasks.map((t,i)=>`<div class="task-line"><b>${i+1}. ${esc(t.title||t.name||'Tarea')}</b><small>${esc(t.duration||'')} min · ${esc(t.space||'')}</small></div>`).join('')||'<p class="muted">Sin tareas.</p>'}</div>`}).join('')}</div></div>`; }
function renderTaskPowerpoint(){ return `<div class="panel"><div class="panel-title"><div><h3>Diseñador de tareas · PowerPoint</h3><small>Slides a la izquierda, campo central, paleta a la derecha. Clic en campo para colocar objetos.</small></div><div><button class="btn" data-slide="new">Nueva slide</button><button class="btn success" data-slide="saveTask">Guardar tarea</button><button class="btn primary" data-slide="sendSession">Enviar a sesión</button></div></div><div class="designer-app"><div class="slide-list">${state.designer.slides.map((s,i)=>`<div class="slide-thumb ${i===state.ui.taskSlideIndex?'active':''}" data-slide-index="${i}"><b>${i+1}. ${esc(s.name)}</b><br><small>${esc(s.meta?.title||'Tarea')}</small></div>`).join('')}</div><div class="pitch-panel">${renderPitchDesigner(false)}</div><div class="palette">${renderPalette()}${renderSlideMeta()}</div></div></div>`; }
function renderPalette(){ const tools=[['playerRed','🔴','Jugador rojo'],['playerBlue','🔵','Jugador azul'],['playerYellow','🟡','Jugador amarillo'],['goalkeeper','⚫','Portero'],['neutral','🟢','Neutral'],['ball','⚽','Balón'],['cone','▲','Cono'],['goal','🥅','Portería'],['line','━','Línea'],['arrow','→','Flecha'],['dashed','- -','Discontinua'],['zone','▭','Zona'],['text','T','Texto'],['image','▧','Imagen']]; return `<div class="palette-section"><h4>Players / Equipment / Fields</h4><div class="tool-grid">${tools.map(([id,icon,title])=>`<button class="tool ${state.ui.selectedTool===id?'active':''}" title="${title}" data-tool="${id}">${icon}</button>`).join('')}</div></div>`; }
function renderSlideMeta(){ const s=state.designer.slides[state.ui.taskSlideIndex]||state.designer.slides[0]; const m=s.meta||{}; const selected=(s.objects||[]).find(o=>o.id===state.ui.selectedObjectId)||(s.objects||[]).at(-1); return `<div class="palette-section"><h4>Datos tarea</h4><label class="field">Título<input id="slideTitle" value="${esc(m.title||'')}"></label><label class="field">Bloque<select id="slideBlock">${taskBlocks.map(b=>`<option ${m.block===b?'selected':''}>${b}</option>`).join('')}</select></label><label class="field">Duración<input id="slideDuration" type="number" value="${m.duration||10}"></label><label class="field">Espacio<input id="slideSpace" value="${esc(m.space||'')}"></label><label class="field">Jugadores<input id="slidePlayers" value="${esc(m.players||'')}"></label><label class="field">Objetivo<textarea id="slideObjective">${esc(m.objective||'')}</textarea></label><label class="field">Normas<textarea id="slideRules">${esc(m.rules||'')}</textarea></label><label class="field">Coaching<textarea id="slideCoaching">${esc(m.coaching||'')}</textarea></label><button class="btn success full" data-slide="saveMeta">Guardar datos slide</button></div><div class="palette-section"><h4>Objeto seleccionado</h4>${selected?`<div class="selected-object-box"><b>${esc(selected.kind)}</b><small>ID ${esc(selected.id.slice(0,6))}</small></div><label class="field">Etiqueta<input id="objectLabel" data-object-prop="label" value="${esc(selected.label||'')}"></label><label class="field">Tamaño<input type="range" min="0.5" max="4" step="0.1" data-object-prop="size" value="${selected.size||1}"></label><label class="field">Color<input type="color" data-object-prop="color" value="${normalizeColor(selected.color||defaultObjectColor(selected.kind))}"></label><div class="form-grid two"><label class="field">X<input type="number" step="0.5" data-object-prop="x" value="${esc(selected.x||0)}"></label><label class="field">Y<input type="number" step="0.5" data-object-prop="y" value="${esc(selected.y||0)}"></label>${['line','arrow','dashed'].includes(selected.kind)?`<label class="field">X2<input type="number" step="0.5" data-object-prop="x2" value="${esc(selected.x2||selected.x+12)}"></label><label class="field">Y2<input type="number" step="0.5" data-object-prop="y2" value="${esc(selected.y2||selected.y)}"></label>`:''}</div><div class="toolbar-row"><button class="btn" data-object="smaller">- pequeño</button><button class="btn" data-object="bigger">+ grande</button><button class="btn" data-object="front">Traer delante</button><button class="btn" data-object="back">Enviar detrás</button><button class="btn" data-object="duplicate">Duplicar</button><button class="btn danger" data-object="delete">Borrar</button></div>`:'<p class="muted">Selecciona un objeto o coloca uno en el campo.</p>'}</div>`; }
function defaultObjectColor(kind){return {playerRed:'#e63946',playerBlue:'#1388ff',playerYellow:'#ffd21f',goalkeeper:'#222222',neutral:'#22c55e',ball:'#ffffff',cone:'#ff5b00',goal:'#dddddd',text:'#ffffff',image:'#ffffff',line:'#111111',arrow:'#111111',dashed:'#111111',zone:'#ffffff'}[kind]||'#ffffff';}
function normalizeColor(c){return /^#[0-9a-fA-F]{6}$/.test(c||'')?c:'#ffffff';}
function renderPitchDesigner(compact=false){ const s=state.designer.slides[state.ui.taskSlideIndex]||state.designer.slides[0]; return `<svg class="pitch-svg" id="pitchSvg" viewBox="0 0 100 64"><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="#111" /></marker></defs>${Array.from({length:10},(_,i)=>`<rect class="pitch-stripe" x="${i*10}" y="0" width="10" height="64"></rect>`).join('')}<rect x="2" y="2" width="96" height="60" class="field-line"></rect><line x1="50" y1="2" x2="50" y2="62" class="field-line"></line><circle cx="50" cy="32" r="7" class="field-line"></circle><rect x="2" y="20" width="16" height="24" class="field-line"></rect><rect x="82" y="20" width="16" height="24" class="field-line"></rect><rect x="2" y="26" width="6" height="12" class="field-line"></rect><rect x="92" y="26" width="6" height="12" class="field-line"></rect><circle cx="50" cy="32" r=".7" fill="#fff"></circle>${(s.objects||[]).map(renderPitchObject).join('')}</svg>`; }
function renderPitchObject(o){ const selected=o.id===state.ui.selectedObjectId; const sel=selected?' selected':''; const size=Number(o.size||1); const color=o.color||defaultObjectColor(o.kind); if(o.kind==='line'||o.kind==='arrow'||o.kind==='dashed')return `<line class="pitch-object${sel}" data-obj="${o.id}" x1="${o.x}" y1="${o.y}" x2="${o.x2||o.x+12}" y2="${o.y2||o.y}" stroke="${color}" stroke-width="${0.7*size}" ${o.kind==='dashed'?'stroke-dasharray="2 1"':''} marker-end="${o.kind==='arrow'?'url(#arrow)':''}"></line>`; if(o.kind==='zone')return `<rect class="pitch-object${sel}" data-obj="${o.id}" x="${o.x}" y="${o.y}" width="${o.w||12*size}" height="${o.h||8*size}" fill="rgba(255,255,255,.12)" stroke="${color}" stroke-width="${0.35*size}" stroke-dasharray="1.5"></rect>`; if(o.kind==='text')return `<text class="pitch-object obj-text${sel}" data-obj="${o.id}" x="${o.x}" y="${o.y}" font-size="${3.3*size}" fill="${color}">${esc(o.label||'Texto')}</text>`; const icon={ball:'⚽',cone:'▲',goal:'▯',goalkeeper:'GK',neutral:'N'}[o.kind]||''; return `<g class="obj-player pitch-object${sel}" data-obj="${o.id}"><circle cx="${o.x}" cy="${o.y}" r="${1.35*size}" fill="${color}" stroke="#111" stroke-width=".25"></circle><text x="${Number(o.x)+1.8*size}" y="${Number(o.y)+.6*size}" class="obj-label" font-size="${2.8*size}">${esc(o.label||icon||'')}</text></g>`; }
function renderTaskBank(){ return `<div class="panel"><div class="panel-title"><h3>Banco de tareas</h3><small>Campo y fuerza</small></div><div class="exercise-grid">${state.tasks.map(t=>`<div class="task-card"><h3>${esc(t.title)}</h3><small>${esc(t.type||'Campo')} · ${esc(t.block||'')} · ${esc(t.duration||'')} min</small><p>${esc(t.objective||'')}</p><button class="btn small" data-load-task="${t.id}">Abrir</button></div>`).join('')||'<p class="muted">Guarda tareas desde el diseñador.</p>'}</div></div>`; }

function renderSvivo(){ const players=state.players; return `<div class="svivo-layout"><div class="panel"><div class="panel-title"><h3>SVIVO campo live</h3><small>WIMU / Polar / ANT+ · posición, velocidad, FC y zonas</small></div><div class="toolbar-row"><button class="btn primary" data-connect="wimu">Conectar WIMU BLE</button><button class="btn" data-connect="ant">Conectar ANT+ USB</button><button class="btn" data-action-svivo="demo">Demo live</button><button class="btn" data-action-svivo="reset">Reset</button></div><div class="svivo-field"><svg viewBox="0 0 100 64">${Array.from({length:10},(_,i)=>`<rect class="pitch-stripe" x="${i*10}" y="0" width="10" height="64"></rect>`).join('')}<rect x="2" y="2" width="96" height="60" class="field-line"></rect><line x1="50" y1="2" x2="50" y2="62" class="field-line"></line><circle cx="50" cy="32" r="7" class="field-line"></circle><rect x="2" y="20" width="16" height="24" class="field-line"></rect><rect x="82" y="20" width="16" height="24" class="field-line"></rect>${players.map((p,i)=>svivoPlayerSvg(p,i)).join('')}</svg></div></div><div>${renderSvivoSide(players)}${renderAntPanel()}</div></div>`; }
function svivoPlayerSvg(p,i){ const live=p.live||{x:20+(i%6)*12,y:16+Math.floor(i/6)*8,speed:Math.random()*26,hr:100+Math.random()*70}; const spz=getSpeedZone(p,live.speed); const {pct,z}=getHrZone(p,live.hr); return `<g><circle cx="${live.x}" cy="${live.y}" r="1.9" fill="${spz.color}" stroke="#061f42" stroke-width=".35"></circle><text x="${live.x+2.2}" y="${live.y+.7}" class="obj-label">${esc(initials(playerName(p)))}</text></g>`; }
function renderSvivoSide(players){return `<div class="panel"><div class="panel-title"><h3>Jugadores live</h3><small>Velocidad / FC</small></div>${players.map(p=>{ const live=p.live||{speed:0,hr:0}; const spz=getSpeedZone(p,live.speed); const {pct,z}=getHrZone(p,live.hr); return `<div class="live-player"><span class="avatar-sm" style="background:${spz.color}">${initials(playerName(p))}</span><div><b>${esc(playerName(p))}</b><br><span class="zone-badge" style="background:${spz.color}">${esc(spz.name)} · ${fmt(live.speed)} km/h</span><br><span class="zone-badge" style="background:${z.color}">${esc(z.name)} · ${fmt(pct,0)}%</span></div><b>${fmt(live.hr,0)}<br><small>ppm</small></b></div>`}).join('')}</div>`; }
function renderAntPanel(){ const a=state.ant; return `<div class="ant-panel"><div class="panel-title"><h3>ANT+ USB</h3><small>Configurable</small></div><div class="form-grid two"><label class="field">Vendor ID<input id="antVendor" value="${esc(a.vendorId)}"></label><label class="field">Product ID<input id="antProduct" value="${esc(a.productId)}"></label><label class="field">Device Number<input id="antDeviceNumber" value="${esc(a.deviceNumber)}"></label><label class="field">Channel<input id="antChannel" value="${esc(a.channel)}"></label><label class="field">Frequency<input id="antFrequency" value="${esc(a.frequency)}"></label><label class="field">Network key<input id="antNetworkKey" value="${esc(a.networkKey)}"></label></div><div class="toolbar-row"><button class="btn primary" data-connect="ant">Conectar ANT+</button><button class="btn" data-ant="save">Guardar config</button><button class="btn" data-ant="diag">Diagnóstico</button></div><div class="diag">Estado: ${esc(a.status)}\nNota: en navegador se intenta WebUSB. Si el stick no permite lectura directa, usa bridge local ANT+ → Supabase/API.</div></div>`;}

function renderCheck(){ const today=todayISO(); return `<div class="panel"><div class="panel-title"><h3>Check-in / Check-out semanal</h3><small>Wellness online, llegada, RPE y devolución GPS/Verity</small></div><div class="check-week">${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'].map((d,i)=>`<div class="check-card"><h3>${d}</h3><p><b>Wellness:</b> antes 12:00</p><p><b>Check-in:</b> llegada + molestias + peso si toca</p><p><b>Check-out:</b> RPE + cómo ha ido + dejar GPS/Verity</p></div>`).join('')}</div></div><div class="panel"><div class="panel-title"><h3>Wellness live</h3><small>Staff view</small></div><div class="wellness-grid">${state.players.map(p=>renderWellnessCard(p,today)).join('')}</div></div>`; }
function renderWellnessCard(p,date){ const w=state.wellness.find(x=>x.playerId===p.id&&x.date===date); const stateCls=!w?'state-pending':(Number(w.pain)>3||Number(w.fatigue)>4?'state-alert':'state-ok'); return `<div class="wellness-card ${stateCls}"><div class="mini-player">${avatarHtml(p,'avatar-sm')}<b>${esc(playerName(p))}</b></div><div class="form-grid two" style="margin-top:8px"><label class="field">Sueño<input data-well="${p.id}|sleep" type="number" min="1" max="5" value="${w?.sleep||''}"></label><label class="field">Fatiga<input data-well="${p.id}|fatigue" type="number" min="1" max="5" value="${w?.fatigue||''}"></label><label class="field">Dolor<input data-well="${p.id}|pain" type="number" min="0" max="10" value="${w?.pain||''}"></label><label class="field">RPE<input data-well="${p.id}|rpe" type="number" min="0" max="10" value="${w?.rpe||''}"></label></div><label class="field">Comentario<textarea data-well="${p.id}|note">${esc(w?.note||'')}</textarea></label></div>`; }

function renderPlayers(){ const p=activePlayer(); return `<div class="profile-layout"><div class="panel profile-pane"><div class="panel-title"><h3>Crear / editar jugador</h3><small>imagen, zonas, perfil</small></div><div class="mini-player" style="margin-bottom:12px">${avatarHtml(p)}<label class="btn">Imagen<input type="file" id="playerPhotoInput" accept="image/*" hidden></label></div><div class="form-grid two">${playerFormFields(p)}</div><label class="field">Descripción<textarea id="playerDescription">${esc(p.description)}</textarea></label><div class="sticky-actions"><button class="btn primary" data-player-save>Guardar jugador</button><button class="btn" data-player-new>Nuevo</button></div></div><div><div class="panel"><div class="panel-title"><h3>${esc(playerName(p))}</h3><small>seguimiento completo</small></div><div class="profile-tabs">${['resumen','fc','velocidad','tests','fuerza','gps','wellness','fisio'].map(t=>`<button class="btn ${state.ui.profileTab===t?'primary':''}" data-profile-tab="${t}">${t}</button>`).join('')}</div>${renderPlayerProfileTab(p)}</div><div class="panel"><h3>Lista jugadores</h3><div class="player-list">${state.players.map(pl=>`<button class="player-card ${pl.id===p.id?'active':''}" data-select-player="${pl.id}">${avatarHtml(pl,'avatar-sm')}<div><b>${esc(playerName(pl))}</b><br><small>${esc(pl.team)} · ${esc(pl.position)}</small></div></button>`).join('')}</div></div></div></div>`; }
function playerFormFields(p){ const f=[['Nombre','firstName'],['Apellido','lastName'],['Fecha nacimiento','birthDate','date'],['Peso','weight'],['Envergadura','wingspan'],['WIMU Name','wimuName'],['Club','club'],['Equipo','team'],['Posición','position'],['Club ID','clubId'],['Deporte','sport'],['Número','number'],['Máx HR','maxHr'],['Máx velocidad','maxSpeed'],['VO2 Max','vo2Max'],['Vel VO2','vo2MaxSpeed'],['Máx Acc','maxAcc'],['Máx Dec','maxDec'],['Lactato máx','maxLactate'],['Lactato V1','lactateSpeed1'],['Lactato V2','lactateSpeed2']]; return f.map(([label,key,type])=>`<label class="field">${label}<input id="pf_${key}" type="${type||'text'}" value="${esc(p[key]||'')}"></label>`).join('');}
function renderPlayerProfileTab(p){ const tab=state.ui.profileTab; if(tab==='fc')return renderZones(p,'hrZones','% HRmax'); if(tab==='velocidad')return renderZones(p,'speedZones','km/h'); if(tab==='tests')return renderTracking(p,'tests',['Fecha','Test','Valor','Unidad','Comentario']); if(tab==='fuerza')return renderTracking(p,'force',['Fecha','Ejercicio','Pico N','Rolling','Lado']); if(tab==='gps')return renderTracking(p,'gps',['Fecha','Distancia','HSR','Sprint','Vmax']); if(tab==='wellness')return renderTracking(p,'wellness',['Fecha','Sueño','Fatiga','Dolor','RPE']); if(tab==='fisio')return renderTracking(p,'physio',['Fecha','Motivo','Tratamiento','Comentario','Estado']); return `<div class="tracking-grid"><div class="tracking-card"><b>${p.maxHr||'-'}</b><span>HR max</span></div><div class="tracking-card"><b>${p.maxSpeed||'-'}</b><span>Vel max</span></div><div class="tracking-card"><b>${p.weight||'-'}</b><span>Peso</span></div><div class="tracking-card"><b>${(p.tests||[]).length}</b><span>Tests</span></div></div>`; }
function renderZones(p,key,unit){ return `<h3>${key==='hrZones'?'Zonas FC individualizadas':'Franjas velocidad individualizadas'}</h3><div class="zones">${(p[key]||[]).map((z,i)=>`<div class="zone-row"><input data-zone="${key}|${i}|name" value="${esc(z.name)}"><input data-zone="${key}|${i}|min" value="${esc(z.min)}"><input data-zone="${key}|${i}|max" value="${esc(z.max)}"><input data-zone="${key}|${i}|color" type="color" value="${z.color}"></div>`).join('')}</div><small class="muted">Unidad: ${unit}</small>`; }
function renderTracking(p,key,headers){ const rows=p[key]||[]; return `<div class="toolbar-row"><button class="btn primary" data-add-tracking="${key}">+ registro</button><button class="btn" data-export-player="${key}">Exportar</button></div><div class="assignment-table-wrap"><table class="result-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.slice().reverse().map(r=>`<tr>${headers.map(h=>`<td>${esc(r[h]||r[h.toLowerCase()]||'')}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length}">Sin datos todavía.</td></tr>`}</tbody></table></div>`; }

function renderDevices(){return `<div class="grid online-device-grid">${state.devices.map(d=>`<div class="device-card ${d.status==='conectado'?'live':''}"><div class="panel-title"><h3>${esc(d.name)}</h3><small>${esc(d.status)}</small></div><p>${d.last?`${esc(d.last.value)} ${esc(d.last.unit||'')}`:'Sin dato'}</p><div class="toolbar-row"><button class="btn primary" data-connect="${d.id}">Conectar</button><button class="btn" data-use-device="${d.id}">Usar</button><button class="btn" data-demo-device="${d.id}">Demo</button></div></div>`).join('')}</div><div class="panel"><div class="panel-title"><h3>BLE Bridge avanzado</h3><small>WIMU / Vitruve / Meloq / ActiveForce2</small></div><div class="form-grid"><label class="field">Dispositivo<select id="bridgeDevice">${['wimu','vitruve','meloq','activeforce2'].map(x=>`<option ${state.bridge.device===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Service UUID<input id="bridgeService" value="${esc(state.bridge.serviceUuid)}"></label><label class="field">Characteristic UUID<input id="bridgeChar" value="${esc(state.bridge.characteristicUuid)}"></label><label class="field">Parser<select id="bridgeParser">${['utf8-json','float32le','int16le','uint16le','csv-line'].map(x=>`<option ${state.bridge.parser===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="toolbar-row"><button class="btn primary" data-connect="bridge">Conectar bridge</button><button class="btn" data-bridge-save>Guardar bridge</button></div></div>${renderAntPanel()}`;}
function renderReports(){ const teamDist=state.results.filter(r=>r.metric==='Distancia').reduce((a,b)=>a+num(b.value),0)||115200; return `<div class="report-hero"><p class="eyebrow">ANÁLISIS DE RENDIMIENTO FÍSICO</p><h1 class="report-title">Resumen físico del partido</h1><div class="report-kpis"><div class="report-kpi"><b>${fmt(teamDist/1000,1)} km</b><span>Distancia total equipo</span></div><div class="report-kpi"><b>26,3 km</b><span>14-21 km/h</span></div><div class="report-kpi"><b>6,7 km</b><span>&gt;21 km/h</span></div><div class="report-kpi"><b>3,1 km</b><span>&gt;24 km/h</span></div></div><div class="tabs"><button class="active">Partido</button><button>Microciclo</button><button>Individual</button><button>Fuerza</button><button>Wellness/fisio</button></div><div class="player-report-grid">${state.players.map((p,i)=>`<div class="player-report-card"><h4>${i+1}. ${esc(playerName(p))}</h4><p>⏱ ${80+i}'</p><p>👟 ${fmt(5+i*.7,1)} km</p><p>⚡ ${fmt(100+i*3,1)} m/min</p><p>🚀 ${fmt((p.maxSpeed||30),1)} km/h</p></div>`).join('')}</div></div>`;}
function renderHistory(){return `<div class="panel"><div class="panel-title"><h3>Historial</h3><small>${state.results.length} registros</small></div><div class="assignment-table-wrap"><table class="result-table"><thead><tr><th>Fecha</th><th>Jugador</th><th>Tipo</th><th>Métrica</th><th>Valor</th><th>Unidad</th><th>Origen</th></tr></thead><tbody>${state.results.slice().reverse().map(r=>`<tr><td>${esc(r.date||r.createdAt||'')}</td><td>${esc(r.playerName||'')}</td><td>${esc(r.type||'')}</td><td>${esc(r.metric||'')}</td><td>${esc(r.value||'')}</td><td>${esc(r.unit||'')}</td><td>${esc(r.source||'')}</td></tr>`).join('')||'<tr><td colspan="7">Sin datos.</td></tr>'}</tbody></table></div></div>`;}
function renderOnline(){return `<div class="split"><div class="panel"><div class="panel-title"><h3>Sala online</h3><small>Supabase/Firebase/API</small></div><div class="form-grid two"><label class="field">Modo<select id="onlineMode">${['Local','Sala online','Supabase/Firebase','API externa'].map(x=>`<option ${state.online.mode===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Sala<input id="onlineRoom" value="${esc(state.online.room)}"></label><label class="field" style="grid-column:1/-1">Endpoint API<input id="onlineEndpoint" value="${esc(state.online.endpoint)}"></label><label class="field" style="grid-column:1/-1">API key<input id="onlineApiKey" type="password" value="${esc(state.online.apiKey)}"></label></div><div class="toolbar-row"><button class="btn primary" data-online="save">Guardar online</button><button class="btn" data-online="sync">Enviar cola</button><button class="btn" data-online="export">Exportar paquete</button><button class="btn danger" data-online="clear">Limpiar cola</button></div><div class="diag">Si no hay endpoint real, la app no hace fetch y trabaja offline. Para varios dispositivos: publicar HTTPS + misma sala + cola sincronizada.</div></div><div class="panel"><div class="panel-title"><h3>Link jugador / wellness</h3><small>QR player</small></div><label class="field">Jugador<select id="playerLinkSelect">${state.players.map(p=>`<option value="${p.id}">${esc(playerName(p))}</option>`).join('')}</select></label><input id="playerLink" value="${location.href.split('#')[0]}?player=${state.players[0]?.id||''}&room=${encodeURIComponent(state.online.room)}" readonly><div class="toolbar-row"><button class="btn" data-copy-link>Copiar link</button></div><div class="qr">QR<br>PLAYER</div></div></div><div class="panel"><h3>Cola de sincronización</h3>${state.online.queue.map(q=>`<div class="queue-item"><b>${esc(q.type)}</b> · ${new Date(q.createdAt).toLocaleString('es-ES')}<br><small>${esc(q.status)}</small></div>`).join('')||'<p class="muted">Sin cola pendiente.</p>'}</div>`;}

function bindTabEvents(){
  // planning
  $$('[data-plan-view]').forEach(b=>b.onclick=()=>{state.ui.planningView=b.dataset.planView;saveState();render();});
  $('#seasonStart')?.addEventListener('change',e=>{state.planning.start=e.target.value;saveState();});
  $('#seasonEnd')?.addEventListener('change',e=>{state.planning.end=e.target.value;saveState();});
  $('#seasonName')?.addEventListener('input',e=>{state.planning.name=e.target.value;saveState();});
  $('#activeWeekSelect')?.addEventListener('change',e=>{state.planning.activeWeekStart=e.target.value; const idx=state.planning.days.findIndex(d=>d.date===e.target.value); if(idx>=0)state.planning.activeDay=idx; saveState(); render();});
  $$('[data-action-plan]').forEach(b=>b.onclick=()=>{ const a=b.dataset.actionPlan; if(a==='fixDates'||a==='newSeason')fixDates(); if(a==='exportPlanning')exportPlanning(); });
  $$('[data-macro-cell]').forEach(td=>td.addEventListener('blur',()=>{ const [date,label]=td.dataset.macroCell.split('|'); setMacroValue(date,label,td.textContent.trim()); }));
  $$('[data-day-value]').forEach(el=>{ const fn=()=>{ const [date,field]=el.dataset.dayValue.split('|'); updateDayValue(date,field,el.value); if(el.matches('select')) render(); }; el.addEventListener(el.matches('textarea,input')?'blur':'change',fn); });
  bindPlanningPlayerInline();
  $$('[data-open-day]').forEach(b=>b.onclick=()=>{state.planning.activeDay=Number(b.dataset.openDay); state.planning.activeWeekStart=weekStartOf(state.planning.days[state.planning.activeDay].date); state.ui.planningView='dia'; saveState(); render();});
  $$('[data-new-event]').forEach(b=>b.onclick=()=>openEventModal(Number(b.dataset.newEvent),null));
  $$('[data-open-event]').forEach(b=>b.onclick=()=>{ const [di,eid]=b.dataset.openEvent.split('|'); openEventModal(Number(di),eid); });
  $$('[data-enter-session]').forEach(b=>b.onclick=()=>{ const [di,eid]=b.dataset.enterSession.split('|'); const day=state.planning.days[Number(di)]; const ev=day?.events.find(x=>x.id===eid); if(ev){state.planning.activeDay=Number(di); state.planning.activeWeekStart=weekStartOf(day.date); state.activeEventId=eid; state.ui.sessionType=ev.sessionType; state.tab='session'; saveState(); render(); }});
  $$('[data-week-shift]').forEach(b=>b.onclick=()=>{state.planning.activeWeekStart=iso(addDays(dateFrom(state.planning.activeWeekStart),Number(b.dataset.weekShift))); const idx=state.planning.days.findIndex(d=>d.date===state.planning.activeWeekStart); if(idx>=0)state.planning.activeDay=idx; saveState(); render();}); $$('[data-jump-week]').forEach(b=>b.onclick=()=>{state.planning.activeWeekStart=b.dataset.jumpWeek; const idx=state.planning.days.findIndex(d=>d.date===b.dataset.jumpWeek); if(idx>=0)state.planning.activeDay=idx; state.ui.planningView='micro'; saveState(); render();});
  $('[data-copy-day]')?.addEventListener('click',()=>{state.clipboard=JSON.parse(JSON.stringify(state.planning.days[state.planning.activeDay])); toast('Día copiado'); saveState();});
  $('[data-paste-day]')?.addEventListener('click',()=>{ if(!state.clipboard)return toast('No hay día copiado'); const target=state.planning.days[state.planning.activeDay]; const copy=JSON.parse(JSON.stringify(state.clipboard)); Object.assign(target,{...copy,id:target.id,date:target.date,day:target.day,events:(copy.events||[]).map(e=>({...e,id:uid()}))}); saveState(); render(); toast('Día pegado'); });
  $$('[data-day-field]').forEach(el=>el.addEventListener('blur',()=>{ const d=state.planning.days[state.planning.activeDay]; d[el.dataset.dayField]=el.value; saveState(); }));

  // session
  $$('[data-session-type]').forEach(b=>b.onclick=()=>{state.ui.sessionType=b.dataset.sessionType; saveState(); render();});
  $('#sessionEventSelect')?.addEventListener('change',e=>{ if(!e.target.value)return; const [di,eid]=e.target.value.split('|'); const day=state.planning.days[Number(di)]; const ev=day.events.find(x=>x.id===eid); state.planning.activeDay=Number(di); state.planning.activeWeekStart=weekStartOf(day.date); state.activeEventId=eid; state.ui.sessionType=ev.sessionType; saveState(); render(); });
  bindSessionAssignmentInputs();
  $$('[data-action-session]').forEach(b=>b.onclick=()=>{ if(b.dataset.actionSession==='addSlideToEvent')addCurrentSlideToEvent(); });
  $('[data-save-session]')?.addEventListener('click',saveSessionSnapshot);

  // tasks
  $$('[data-slide-index]').forEach(b=>b.onclick=()=>{state.ui.taskSlideIndex=Number(b.dataset.slideIndex); saveState(); render();});
  $$('[data-tool]').forEach(b=>b.onclick=()=>{state.ui.selectedTool=b.dataset.tool; saveState(); render();});
  $('#pitchSvg')?.addEventListener('click',pitchClick);
  $('#pitchSvg')?.addEventListener('mousedown',pitchMouseDown);
  document.addEventListener('mousemove',pitchMouseMove);
  document.addEventListener('mouseup',()=>currentDrag=null);
  $$('[data-slide]').forEach(b=>b.onclick=()=>handleSlideAction(b.dataset.slide));
  $$('[data-object]').forEach(b=>b.onclick=()=>handleObjectAction(b.dataset.object)); $$('[data-object-prop]').forEach(el=>el.oninput=()=>updateSelectedObjectProp(el));
  $$('[data-load-task]').forEach(b=>b.onclick=()=>loadTaskToSlide(b.dataset.loadTask));

  // force and VBT
  $$('[data-force]').forEach(b=>b.onclick=()=>handleForce(b.dataset.force));
  ['forceDevice','forceMode','forceExercise','forceSide','forceRolling','forceHz'].forEach(id=>$('#'+id)?.addEventListener('change',updateForceConfig));
  setTimeout(drawForceCurve,0);
  $$('[data-vbt]').forEach(b=>b.onclick=()=>handleVbt(b.dataset.vbt));

  // devices
  $$('[data-connect]').forEach(b=>b.onclick=()=>connectDevice(b.dataset.connect));
  $$('[data-use-device]').forEach(b=>b.onclick=()=>{state.activeDeviceId=b.dataset.useDevice; saveState(); render();});
  $$('[data-demo-device]').forEach(b=>b.onclick=()=>startDeviceDemo(b.dataset.demoDevice));
  $('[data-bridge-save]')?.addEventListener('click',saveBridgeConfig);
  $$('[data-ant]').forEach(b=>b.onclick=()=>handleAnt(b.dataset.ant));
  $$('[data-action-svivo]').forEach(b=>b.onclick=()=>handleSvivo(b.dataset.actionSvivo));

  // player
  $$('[data-select-player]').forEach(b=>b.onclick=()=>{state.activePlayerId=b.dataset.selectPlayer; saveState(); render();});
  $$('[data-profile-tab]').forEach(b=>b.onclick=()=>{state.ui.profileTab=b.dataset.profileTab; saveState(); render();});
  $('[data-player-save]')?.addEventListener('click',savePlayerProfile);
  $('[data-player-new]')?.addEventListener('click',()=>{const p=makePlayer({firstName:'Nuevo',lastName:'Jugador'}); state.players.push(p); state.activePlayerId=p.id; saveState(); render();});
  $('#playerPhotoInput')?.addEventListener('change',savePlayerPhoto);
  $$('[data-zone]').forEach(el=>el.addEventListener('input',()=>updateZone(el)));
  $$('[data-add-tracking]').forEach(b=>b.onclick=()=>addTracking(b.dataset.addTracking));
  $$('[data-export-player]').forEach(b=>b.onclick=()=>exportPlayerTracking(b.dataset.exportPlayer));

  // wellness
  $$('[data-well]').forEach(el=>el.addEventListener('input',()=>updateWellness(el)));

  // online
  $$('[data-online]').forEach(b=>b.onclick=()=>handleOnline(b.dataset.online));
  $('[data-copy-link]')?.addEventListener('click',()=>{navigator.clipboard?.writeText($('#playerLink').value); toast('Link copiado');});
  $('#playerLinkSelect')?.addEventListener('change',e=>{$('#playerLink').value=`${location.href.split('#')[0]}?player=${e.target.value}&room=${encodeURIComponent(state.online.room)}`});
}
function bindPlanningPlayerInline(){
  $$('[data-pd-assign]').forEach(el=>el.addEventListener('change',()=>{ const [date,pid]=el.dataset.pdAssign.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; assignmentRecord(ev,pid).selected=el.checked; saveState(); render(); }));
  $$('[data-pd-min]').forEach(el=>el.addEventListener('change',()=>{ const [date,pid]=el.dataset.pdMin.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; const r=assignmentRecord(ev,pid); r.minutes=num(el.value); if(r.minutes>0) r.selected=true; saveState(); }));
  $$('[data-pd-role]').forEach(el=>el.addEventListener('blur',()=>{ const [date,pid]=el.dataset.pdRole.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; assignmentRecord(ev,pid).role=el.value; saveState(); }));
  $$('[data-pd-avail]').forEach(el=>el.addEventListener('change',()=>{ const [date,pid]=el.dataset.pdAvail.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; const r=assignmentRecord(ev,pid); r.availability=el.value; r.selected=true; saveState(); render(); }));
  $$('[data-pd-comment]').forEach(el=>el.addEventListener('blur',()=>{ const [date,pid]=el.dataset.pdComment.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; ev.individual=ev.individual||{}; ev.individual[pid]=el.value; saveState(); }));
  $$('[data-pd-fisio]').forEach(el=>el.addEventListener('change',()=>{ const [date,pid]=el.dataset.pdFisio.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; ev.physio=ev.physio||{}; ev.physio[pid]=ev.physio[pid]||{}; ev.physio[pid].done=el.checked; saveState(); render(); }));
  $$('[data-pd-fisio-note]').forEach(el=>el.addEventListener('blur',()=>{ const [date,pid]=el.dataset.pdFisioNote.split('|'); const ev=ensureDayPlanningEvent(date); if(!ev)return; ev.physio=ev.physio||{}; ev.physio[pid]=ev.physio[pid]||{}; ev.physio[pid].note=el.value; saveState(); }));
}
function bindSessionAssignmentInputs(){
  const cur=getActiveEvent(); const ev=cur.event; if(!ev)return;
  state.players.forEach(p=>{
    $(`[data-session-assign="${p.id}"]`)?.addEventListener('change',e=>{assignmentRecord(ev,p.id).selected=e.target.checked; saveState();});
    $(`[data-session-minutes="${p.id}"]`)?.addEventListener('change',e=>{assignmentRecord(ev,p.id).minutes=num(e.target.value); saveState();});
    $(`[data-session-availability="${p.id}"]`)?.addEventListener('change',e=>{assignmentRecord(ev,p.id).availability=e.target.value; saveState();});
    $(`[data-session-role="${p.id}"]`)?.addEventListener('input',e=>{assignmentRecord(ev,p.id).role=e.target.value; saveState();});
    $(`[data-session-individual="${p.id}"]`)?.addEventListener('input',e=>{ev.individual[p.id]=e.target.value; saveState();});
    $(`[data-session-physio="${p.id}"]`)?.addEventListener('change',e=>{ev.physio[p.id]=ev.physio[p.id]||{}; ev.physio[p.id].done=e.target.checked; saveState();});
    $(`[data-session-physio-note="${p.id}"]`)?.addEventListener('input',e=>{ev.physio[p.id]=ev.physio[p.id]||{}; ev.physio[p.id].note=e.target.value; saveState();});
  });
}
function updateForceConfig(){ state.force.device=$('#forceDevice')?.value||state.force.device; state.force.mode=$('#forceMode')?.value||state.force.mode; state.force.exercise=$('#forceExercise')?.value||state.force.exercise; state.force.side=$('#forceSide')?.value||state.force.side; state.force.rolling=num($('#forceRolling')?.value||2)||2; state.force.sampleHz=num($('#forceHz')?.value||80)||80; saveState(); }

function simulateData(){ const d=activeDevice(); d.status='conectado'; d.last={value: d.id==='polar'?Math.round(110+Math.random()*60):d.id==='vitruve'?fmt(0.4+Math.random()*.8,2):fmt(200+Math.random()*500,1),unit:d.id==='polar'?'ppm':d.id==='vitruve'?'m/s':'N',at:new Date().toISOString()}; if(d.id==='polar'){d.last.players=Object.fromEntries(state.players.map(p=>[p.id,Math.round(100+Math.random()*75)]));} if(['tindeq','meloq','activeforce2','chronojump'].includes(d.id)&&state.force.capturing)pushForceSample(num(d.last.value)); saveState(); render(); }
async function connectDevice(id){
  if(id==='polar')return connectPolar();
  if(id==='wimu'||id==='vitruve'||id==='meloq'||id==='activeforce2')return connectGenericBle(id);
  if(id==='bridge')return connectBleBridge();
  if(id==='ant')return connectAntUsb();
  if(id==='tindeq')return connectTindeqLike();
  if(id==='chronojump')return connectSerial('chronojump');
  toast('Dispositivo no configurado');
}
async function connectPolar(){ try{ if(!navigator.bluetooth)throw new Error('Web Bluetooth no disponible'); const device=await navigator.bluetooth.requestDevice({filters:[{services:['heart_rate']}],optionalServices:['battery_service']}); const server=await device.gatt.connect(); const service=await server.getPrimaryService('heart_rate'); const ch=await service.getCharacteristic('heart_rate_measurement'); await ch.startNotifications(); ch.addEventListener('characteristicvaluechanged',e=>{const v=e.target.value; const flags=v.getUint8(0); const hr=flags&1?v.getUint16(1,true):v.getUint8(1); updateDevice('polar',hr,'ppm','FC');}); updateStatus('polar','conectado'); toast('Polar conectado'); }catch(e){updateStatus('polar','error');toast('Polar: '+e.message);} }
async function connectGenericBle(id){ try{ if(!navigator.bluetooth)throw new Error('Web Bluetooth no disponible'); const filters=id==='wimu'?[{namePrefix:'WIMU'},{namePrefix:'Wimu'},{namePrefix:'Hudl'}]:id==='vitruve'?[{namePrefix:'Vitruve'},{namePrefix:'VITRUVE'},{namePrefix:'Encoder'}]:[{namePrefix:id},{namePrefix:id.toUpperCase()}]; const device=await navigator.bluetooth.requestDevice({filters,optionalServices:['battery_service','device_information']}); await device.gatt.connect(); updateStatus(id,'conectado'); toast(`${getDevice(id).name} emparejado. Si expone GATT legible, usa BLE Bridge con UUID.`); }catch(e){updateStatus(id,'error');toast(`${id}: ${e.message}`);} }
async function connectBleBridge(){ saveBridgeConfig(); try{ if(!navigator.bluetooth)throw new Error('Web Bluetooth no disponible'); if(!state.bridge.serviceUuid||!state.bridge.characteristicUuid)throw new Error('Faltan Service UUID y Characteristic UUID'); const device=await navigator.bluetooth.requestDevice({acceptAllDevices:true,optionalServices:[state.bridge.serviceUuid]}); const server=await device.gatt.connect(); const service=await server.getPrimaryService(state.bridge.serviceUuid); const ch=await service.getCharacteristic(state.bridge.characteristicUuid); await ch.startNotifications(); ch.addEventListener('characteristicvaluechanged',e=>parseBridgeData(e.target.value,state.bridge.device)); updateStatus(state.bridge.device,'conectado'); toast('BLE bridge conectado'); }catch(e){toast('BLE bridge: '+e.message);} }
function parseBridgeData(view,deviceId){ const parser=state.bridge.parser; let value=null, payload={}; try{ if(parser==='float32le') value=view.getFloat32(0,true); else if(parser==='int16le') value=view.getInt16(0,true); else if(parser==='uint16le') value=view.getUint16(0,true); else { const text=new TextDecoder().decode(view.buffer); if(parser==='utf8-json') payload=JSON.parse(text); else if(parser==='csv-line'){const [player,speed,hr,x,y]=text.split(','); payload={player,speed:num(speed),hr:num(hr),x:num(x),y:num(y)};} } }catch(e){} if(value!==null)updateDevice(deviceId,value,deviceId==='vitruve'?'m/s':'N','BLE'); if(payload.player||payload.speed||payload.hr){applyLivePayload(payload);} }
function applyLivePayload(payload){ const p=state.players.find(x=>x.wimuName===payload.player||playerName(x)===payload.player)||state.players[0]; p.live={x:payload.x||Math.random()*80+10,y:payload.y||Math.random()*50+7,speed:num(payload.speed),hr:num(payload.hr)}; queue('live', {playerId:p.id,...p.live}); saveState(); if(state.tab==='svivo')render(); }
async function connectTindeqLike(){ try{ if(!navigator.bluetooth)throw new Error('Web Bluetooth no disponible'); const device=await navigator.bluetooth.requestDevice({filters:[{namePrefix:'Progressor'},{namePrefix:'Tindeq'}],optionalServices:['7e4e1701-1ea6-40c9-9dcc-13d34ffead57','battery_service']}); await device.gatt.connect(); updateStatus('tindeq','conectado'); toast('Tindeq conectado/emparejado'); }catch(e){updateStatus('tindeq','error');toast('Tindeq: '+e.message);} }
async function connectSerial(id){ try{ if(!navigator.serial)throw new Error('Web Serial no disponible'); const port=await navigator.serial.requestPort(); await port.open({baudRate:115200}); updateStatus(id,'conectado'); toast(`${id} conectado por serial`); const decoder=new TextDecoderStream(); port.readable.pipeTo(decoder.writable); const reader=decoder.readable.getReader(); let buffer=''; while(true){ const {value,done}=await reader.read(); if(done)break; buffer+=value; const lines=buffer.split(/\r?\n/); buffer=lines.pop(); for(const line of lines){ const m=line.match(/-?\d+(?:[.,]\d+)?/); if(m){ const n=num(m[0]); updateDevice(id,n,'N','Fuerza'); if(state.force.capturing)pushForceSample(n); } } } }catch(e){updateStatus(id,'error');toast(`${id}: ${e.message}`);} }
async function connectAntUsb(){ saveAntConfig(); try{ if(!navigator.usb)throw new Error('WebUSB no disponible en este navegador'); const filters=[]; if(state.ant.vendorId){filters.push({vendorId:parseInt(state.ant.vendorId)});} const device=await navigator.usb.requestDevice({filters}); await device.open(); if(device.configuration===null)await device.selectConfiguration(1); updateStatus('ant','conectado'); state.ant.status=`Conectado USB: ${device.productName||'ANT+ stick'} · device ${state.ant.deviceNumber} · channel ${state.ant.channel}`; toast('ANT+ USB conectado. Falta bridge/protocolo para interpretar WIMU si no emite estándar.'); saveState(); render(); }catch(e){updateStatus('ant','error'); state.ant.status='Error: '+e.message; toast('ANT+: '+e.message); saveState(); render();} }
function updateStatus(id,status){ const d=getDevice(id); d.status=status; saveState(); }
function updateDevice(id,value,unit,metric){ const d=getDevice(id); d.status='conectado'; d.last={value,unit,metric,at:new Date().toISOString()}; if(['tindeq','meloq','activeforce2','chronojump'].includes(id)&&state.force.capturing)pushForceSample(num(value)); queue('device',{id,value,unit,metric}); saveState(); }
function startDeviceDemo(id){ clearInterval(demoIntervals[id]); updateStatus(id,'conectado'); demoIntervals[id]=setInterval(()=>{ if(id==='polar'){const players=Object.fromEntries(state.players.map(p=>[p.id,Math.round(95+Math.random()*80)])); getDevice('polar').last={value:Object.values(players)[0],unit:'ppm',metric:'FC',players};} else if(id==='wimu'){state.players.forEach((p,i)=>p.live={x:10+Math.random()*80,y:7+Math.random()*50,speed:Math.random()*32,hr:95+Math.random()*80});} else updateDevice(id, id==='vitruve'?Number((0.35+Math.random()*1.1).toFixed(2)):Number((180+Math.random()*600).toFixed(1)), id==='vitruve'?'m/s':'N','Demo'); saveState(); if(['svivo','session','devices'].includes(state.tab))render(); },1000); toast('Demo iniciada: '+id); }

function handleForce(action){ updateForceConfig(); if(action==='start'){state.force.capturing=true;state.force.samples=[];state.force.start=Date.now();toast('Captura de fuerza iniciada');} if(action==='stop'){state.force.capturing=false;toast('Captura parada');} if(action==='reset'){state.force.samples=[];state.force.capturing=false;} if(action==='demo')demoForce(); if(action==='save')saveForceTest(); saveState(); render(); }
function pushForceSample(y){ const t=state.force.start?(Date.now()-state.force.start)/1000:(state.force.samples.length/(state.force.sampleHz||80)); state.force.samples.push({t:Number(t.toFixed(3)),y:Number(y)}); if(state.force.samples.length>2400)state.force.samples.shift(); }
function demoForce(){ state.force.capturing=true; state.force.samples=[]; state.force.start=Date.now(); let i=0; const total=420; clearInterval(demoIntervals.force); demoIntervals.force=setInterval(()=>{ const phase=i/total; const base=Math.sin(Math.min(Math.PI,phase*Math.PI))*520; const plateau=phase>.28&&phase<.72?450:0; const y=Math.max(0,(plateau||base)+Math.random()*20); pushForceSample(y); i++; if(i>total){clearInterval(demoIntervals.force); state.force.capturing=false; saveState(); render();} if(i%6===0&&state.tab==='session')drawForceCurve(); },18); }
function forceSummary(){ const s=state.force.samples||[]; if(!s.length)return {peak:0,roll:0,rfd:0,impulse:0}; const peak=Math.max(...s.map(x=>x.y)); const win=state.force.rolling||2; let roll=0,sum=0,start=0; for(let end=0;end<s.length;end++){sum+=s[end].y; while(s[end].t-s[start].t>win&&start<end){sum-=s[start].y;start++;} roll=Math.max(roll,sum/(end-start+1));} const first=s[0]; const s200=s.find(x=>x.t>=0.2)||s[Math.min(10,s.length-1)]; const rfd=(s200.y-first.y)/Math.max(.001,(s200.t-first.t)); let impulse=0; for(let i=1;i<s.length;i++){impulse+=((s[i-1].y+s[i].y)/2)*(s[i].t-s[i-1].t)} return {peak,roll,rfd,impulse}; }
function drawForceCurve(){ const c=$('#forceCanvas'); if(!c)return; const ctx=c.getContext('2d'); const w=c.width,h=c.height; ctx.clearRect(0,0,w,h); ctx.fillStyle='#fff'; ctx.fillRect(0,0,w,h); const pad={l:55,r:20,t:24,b:40}; ctx.strokeStyle='#d7e3f4'; ctx.lineWidth=1; for(let i=0;i<6;i++){let y=pad.t+(h-pad.t-pad.b)*i/5;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();} for(let i=0;i<8;i++){let x=pad.l+(w-pad.l-pad.r)*i/7;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,h-pad.b);ctx.stroke();} const s=state.force.samples||[]; if(!s.length){ctx.fillStyle='#72839a';ctx.font='18px Arial';ctx.fillText('Sin curva capturada',80,180);return;} const maxY=Math.max(...s.map(x=>x.y),10), maxT=Math.max(...s.map(x=>x.t),1); ctx.strokeStyle='#0b63ce';ctx.lineWidth=3;ctx.beginPath(); s.forEach((p,i)=>{const x=pad.l+p.t/maxT*(w-pad.l-pad.r); const y=h-pad.b-p.y/maxY*(h-pad.t-pad.b); if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y);});ctx.stroke(); const sm=forceSummary(); ctx.fillStyle='#073a74';ctx.font='bold 15px Arial';ctx.fillText(`Pico ${fmt(sm.peak)} N · Rolling ${state.force.rolling}s ${fmt(sm.roll)} N · RFD ${fmt(sm.rfd)} N/s`,pad.l,18); ctx.fillStyle='#5c728c';ctx.font='13px Arial';ctx.fillText('Newtons',8,30);ctx.fillText('Tiempo (s)',w/2,h-10); }
function saveForceTest(){ const p=activePlayer(); const sm=forceSummary(); const img=$('#forceCanvas')?.toDataURL('image/png')||''; const rec={Fecha:todayISO(),Ejercicio:state.force.exercise,'Pico N':fmt(sm.peak),'Rolling':fmt(sm.roll),Lado:state.force.side,curve:img}; p.force.push(rec); state.results.push({date:todayISO(),playerId:p.id,playerName:playerName(p),type:'Fuerza',metric:'Pico N',value:sm.peak,unit:'N',source:state.force.device,extra:{summary:sm,curve:img}}); queue('force',rec); toast('Test de fuerza guardado'); saveState(); }
function handleVbt(action){ state.vbtReps=state.vbtReps||[]; if(action==='addRep'){ const mean=num($('#vbtMean').value), peak=num($('#vbtPeak').value), load=num($('#vbtLoad').value); const best=state.vbtReps.length?Math.max(...state.vbtReps.map(r=>r.mean),mean):mean; const loss=best?Math.max(0,(best-mean)/best*100):0; state.vbtReps.push({mean,peak,power:fmt(load*9.81*mean,0),loss:fmt(loss,1)}); } if(action==='saveSet'){ const p=activePlayer(); p.force.push({Fecha:todayISO(),Ejercicio:$('#vbtExercise').value,'Pico N':'','Rolling':'',Lado:'VBT',reps:state.vbtReps}); state.results.push({date:todayISO(),playerId:p.id,playerName:playerName(p),type:'VBT',metric:'Reps',value:state.vbtReps.length,unit:'rep',source:'Vitruve/manual'}); state.vbtReps=[]; toast('Serie VBT guardada'); } saveState(); render(); }

function pitchClick(e){ const svg=e.currentTarget; if(e.target.closest('[data-obj]'))return; const pt=svgPoint(svg,e); const slide=state.designer.slides[state.ui.taskSlideIndex]; const kind=state.ui.selectedTool; const obj={id:uid(),kind,x:Number(pt.x.toFixed(1)),y:Number(pt.y.toFixed(1)),size:1,color:defaultObjectColor(kind),label:kind.startsWith('player')?String((slide.objects||[]).filter(o=>o.kind.startsWith('player')).length+1):(kind==='text'?'Texto':'')}; if(['line','arrow','dashed'].includes(kind)){obj.x2=obj.x+15;obj.y2=obj.y;} if(kind==='zone'){obj.w=14;obj.h=9;} slide.objects.push(obj); state.ui.selectedObjectId=obj.id; saveState(); render(); }
function svgPoint(svg,e){ const p=svg.createSVGPoint(); p.x=e.clientX; p.y=e.clientY; return p.matrixTransform(svg.getScreenCTM().inverse()); }
function pitchMouseDown(e){ const g=e.target.closest('[data-obj]'); if(!g)return; state.ui.selectedObjectId=g.dataset.obj; const svg=$('#pitchSvg'); const pt=svgPoint(svg,e); currentDrag={id:g.dataset.obj,dx:pt.x,dy:pt.y}; saveState(); }
function pitchMouseMove(e){ if(!currentDrag||!$('#pitchSvg'))return; const svg=$('#pitchSvg'); const pt=svgPoint(svg,e); const slide=state.designer.slides[state.ui.taskSlideIndex]; const obj=slide.objects.find(o=>o.id===currentDrag.id); if(obj){obj.x=Number(pt.x.toFixed(1));obj.y=Number(pt.y.toFixed(1)); saveState(); render();} }
function handleSlideAction(action){ const slide=state.designer.slides[state.ui.taskSlideIndex]; if(action==='new'){state.designer.slides.push(blankSlide()); state.ui.taskSlideIndex=state.designer.slides.length-1;} if(action==='saveMeta')saveSlideMeta(); if(action==='saveTask'){saveSlideMeta(); const s=state.designer.slides[state.ui.taskSlideIndex]; const task={id:uid(),type:'Campo',...s.meta,objects:s.objects,graphic:JSON.parse(JSON.stringify(s))}; state.tasks.push(task); toast('Tarea guardada al banco');} if(action==='sendSession')addCurrentSlideToEvent(); saveState(); render(); }
function saveSlideMeta(){ const s=state.designer.slides[state.ui.taskSlideIndex]; Object.assign(s.meta,{title:$('#slideTitle')?.value||s.meta.title,block:$('#slideBlock')?.value||s.meta.block,duration:$('#slideDuration')?.value||s.meta.duration,space:$('#slideSpace')?.value||s.meta.space,players:$('#slidePlayers')?.value||s.meta.players,objective:$('#slideObjective')?.value||s.meta.objective,rules:$('#slideRules')?.value||s.meta.rules,coaching:$('#slideCoaching')?.value||s.meta.coaching}); s.name=s.meta.title; }
function addCurrentSlideToEvent(){ saveSlideMeta(); const ev=getActiveEvent().event; if(!ev)return toast('Selecciona un evento'); const s=state.designer.slides[state.ui.taskSlideIndex]; ev.tasks=ev.tasks||[]; ev.tasks.push({id:uid(),type:'Campo',...s.meta,objects:JSON.parse(JSON.stringify(s.objects)),graphic:JSON.parse(JSON.stringify(s))}); toast('Tarea añadida al evento'); saveState(); render(); }
function getSelectedObject(){const slide=state.designer.slides[state.ui.taskSlideIndex]; return (slide.objects||[]).find(o=>o.id===state.ui.selectedObjectId)||slide.objects.at(-1);}
function updateSelectedObjectProp(el){ const obj=getSelectedObject(); if(!obj)return; const prop=el.dataset.objectProp; obj[prop]=['x','y','x2','y2','size'].includes(prop)?num(el.value):el.value; saveState(); render(); }
function handleObjectAction(action){ const slide=state.designer.slides[state.ui.taskSlideIndex]; const obj=getSelectedObject(); if(!obj)return; if(action==='delete'){slide.objects=slide.objects.filter(o=>o.id!==obj.id); state.ui.selectedObjectId=null;} if(action==='duplicate'){const copy={...obj,id:uid(),x:Number(obj.x)+3,y:Number(obj.y)+3}; slide.objects.push(copy); state.ui.selectedObjectId=copy.id;} if(action==='bigger')obj.size=Number((Number(obj.size||1)+0.2).toFixed(1)); if(action==='smaller')obj.size=Math.max(0.4,Number((Number(obj.size||1)-0.2).toFixed(1))); if(action==='front'){slide.objects=slide.objects.filter(o=>o.id!==obj.id); slide.objects.push(obj);} if(action==='back'){slide.objects=slide.objects.filter(o=>o.id!==obj.id); slide.objects.unshift(obj);} saveState(); render(); }
function loadTaskToSlide(id){ const t=state.tasks.find(x=>x.id===id); if(!t)return; state.designer.slides.push(t.graphic||{...blankSlide(),meta:t}); state.ui.taskSlideIndex=state.designer.slides.length-1; saveState(); render(); }

function handleSvivo(action){ if(action==='demo'){startDeviceDemo('wimu'); toast('Demo SVIVO iniciada');} if(action==='reset'){state.players.forEach(p=>delete p.live); saveState(); render();} }
function saveAntConfig(){ state.ant.vendorId=$('#antVendor')?.value||state.ant.vendorId; state.ant.productId=$('#antProduct')?.value||state.ant.productId; state.ant.deviceNumber=$('#antDeviceNumber')?.value||state.ant.deviceNumber; state.ant.channel=$('#antChannel')?.value||state.ant.channel; state.ant.frequency=$('#antFrequency')?.value||state.ant.frequency; state.ant.networkKey=$('#antNetworkKey')?.value||state.ant.networkKey; saveState(); }
function handleAnt(action){ if(action==='save'){saveAntConfig(); toast('ANT+ config guardada');} if(action==='diag'){saveAntConfig(); state.ant.status=`Diagnóstico: WebUSB ${navigator.usb?'OK':'NO'} · channel ${state.ant.channel} · device ${state.ant.deviceNumber} · freq ${state.ant.frequency}`; saveState(); render();} }
function saveBridgeConfig(){ state.bridge.device=$('#bridgeDevice')?.value||state.bridge.device; state.bridge.serviceUuid=$('#bridgeService')?.value||state.bridge.serviceUuid; state.bridge.characteristicUuid=$('#bridgeChar')?.value||state.bridge.characteristicUuid; state.bridge.parser=$('#bridgeParser')?.value||state.bridge.parser; saveState(); toast('Bridge guardado'); }

function savePlayerProfile(){ const p=activePlayer(); ['firstName','lastName','birthDate','weight','wingspan','wimuName','club','team','position','clubId','sport','number','maxHr','maxSpeed','vo2Max','vo2MaxSpeed','maxAcc','maxDec','maxLactate','lactateSpeed1','lactateSpeed2'].forEach(k=>{const el=$(`#pf_${k}`); if(el)p[k]=el.value;}); p.description=$('#playerDescription')?.value||p.description; saveState(); render(); toast('Jugador guardado'); }
async function savePlayerPhoto(e){ const file=e.target.files?.[0]; if(!file)return; const data=await compressImage(file,420,0.78); activePlayer().photo=data; saveState(); render(); toast('Imagen guardada en perfil'); }
function compressImage(file,max=420,q=.8){ return new Promise(res=>{ const img=new Image(); const r=new FileReader(); r.onload=()=>{img.onload=()=>{const c=document.createElement('canvas'); const scale=Math.min(1,max/Math.max(img.width,img.height)); c.width=Math.round(img.width*scale); c.height=Math.round(img.height*scale); c.getContext('2d').drawImage(img,0,0,c.width,c.height); res(c.toDataURL('image/jpeg',q));}; img.src=r.result;}; r.readAsDataURL(file); }); }
function updateZone(el){ const [key,i,field]=el.dataset.zone.split('|'); activePlayer()[key][Number(i)][field]=field==='name'||field==='color'?el.value:num(el.value); saveState(); }
function addTracking(key){ const p=activePlayer(); const rec={Fecha:todayISO(),Test:'Nuevo',Valor:'',Unidad:'',Comentario:''}; if(key==='force')Object.assign(rec,{Ejercicio:'Nuevo','Pico N':'',Rolling:'',Lado:''}); if(key==='gps')Object.assign(rec,{Distancia:'',HSR:'',Sprint:'',Vmax:''}); if(key==='wellness')Object.assign(rec,{Sueño:'',Fatiga:'',Dolor:'',RPE:''}); if(key==='physio')Object.assign(rec,{Motivo:'',Tratamiento:'',Estado:''}); p[key].push(rec); saveState(); render(); }
function exportPlayerTracking(key){ const p=activePlayer(); downloadText(toCsv(p[key]||[]),`${playerName(p)}_${key}.csv`,'text/csv'); }
function updateWellness(el){ const [pid,field]=el.dataset.well.split('|'); let w=state.wellness.find(x=>x.playerId===pid&&x.date===todayISO()); if(!w){w={id:uid(),playerId:pid,date:todayISO()}; state.wellness.push(w);} w[field]=el.value; const p=state.players.find(x=>x.id===pid); p.wellness=p.wellness||[]; const pw=p.wellness.find(x=>x.Fecha===todayISO())||{Fecha:todayISO()}; pw[field]=el.value; if(!p.wellness.includes(pw))p.wellness.push(pw); queue('wellness',w); saveState(); }

function handleOnline(action){ if(action==='save'){state.online.mode=$('#onlineMode').value;state.online.room=$('#onlineRoom').value;state.online.endpoint=$('#onlineEndpoint').value;state.online.apiKey=$('#onlineApiKey').value;toast('Online guardado');} if(action==='clear'){state.online.queue=[];toast('Cola limpiada');} if(action==='export')downloadText(JSON.stringify({queue:state.online.queue,state},null,2),`arlab_online_${todayISO()}.json`,'application/json'); if(action==='sync')pushSyncQueue(); saveState(); render(); }
async function pushSyncQueue(){ const ep=state.online.endpoint; if(!ep||/tu-api|example|localhost:0/i.test(ep)){toast('No hay endpoint real. Se mantiene offline sin Failed to fetch.');return;} try{ const res=await fetch(ep,{method:'POST',headers:{'Content-Type':'application/json','Authorization':state.online.apiKey?`Bearer ${state.online.apiKey}`:''},body:JSON.stringify({room:state.online.room,items:state.online.queue})}); if(!res.ok)throw new Error(res.statusText); state.online.queue=[]; state.online.lastSync=new Date().toISOString(); toast('Cola enviada'); }catch(e){toast('No se pudo sincronizar: '+e.message);} }
function saveSessionSnapshot(){ const ev=getActiveEvent().event; state.sessions.push({id:uid(),date:todayISO(),eventId:ev?.id,type:state.ui.sessionType,players:ev?.assignments||{},createdAt:new Date().toISOString()}); queue('session',state.sessions.at(-1)); saveState(); toast('Sesión guardada'); }
function exportPlanning(){ const rows=state.planning.days.map(d=>({fecha:d.date,dia:d.day,md:d.md,periodo:d.period,subperiodo:d.subperiod,rival:d.rival,am:d.am,pm:d.pm,carga:d.load,comentario:d.comment,eventos:d.events.map(e=>`${e.type}${e.number} ${e.time} ${e.sessionType}`).join(' | ')})); downloadText(toCsv(rows),`planificacion_${state.planning.name}.csv`,'text/csv'); }
function exportCsv(){ downloadText(toCsv(state.results),`arlab_datos_${todayISO()}.csv`,'text/csv'); }
function backupJson(){ hardSave(); downloadText(JSON.stringify(state,null,2),`arlab_backup_${todayISO()}.json`,'application/json'); }
function importJson(e){ const f=e.target.files?.[0]; if(!f)return; const r=new FileReader(); r.onload=()=>{try{state=hydrate(JSON.parse(r.result)); hardSave(); render(); toast('Backup importado');}catch(err){toast('JSON no válido')}}; r.readAsText(f); }
function toCsv(rows){ if(!rows?.length)return ''; const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))]; return [headers.join(';'),...rows.map(r=>headers.map(h=>csvCell(r[h])).join(';'))].join('\n'); }
function csvCell(v){ const s=typeof v==='object'?JSON.stringify(v):String(v??''); return /[;"\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s; }
function downloadText(text,name,type){ const blob=new Blob([text],{type}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click(); URL.revokeObjectURL(a.href); }

if('serviceWorker' in navigator){ navigator.serviceWorker.register('service-worker.js').catch(()=>{}); }
render();
